function formatDurationShort(ms){if(ms<=0)return '0s';var s=Math.floor(ms/1000);if(s<60)return s+'s';var m=Math.floor(s/60);if(m<60)return m+'m '+(s%60)+'s';var h=Math.floor(m/60);if(h<24)return h+'h '+(m%60)+'m';var d=Math.floor(h/24);return d+'d '+(h%24)+'h';}
