function openBuyPasses(){var t=document.getElementById('pageTitle');if(t)t.innerText='🎟️ Buy Passes';var vb=(currentUser&&currentUser.isVIP)?'<button class="btn-claim" style="width:100%;background:#6c757d;cursor:not-allowed" disabled>Already Bought!</button>':'<button class="btn-claim" style="width:100%" onclick="purchasePass(\'VIP\')">Buy VIP Pass</button>';var pb=(currentUser&&currentUser.isPremium)?'<button class="btn-claim" style="width:100%;background:#6c757d;cursor:not-allowed" disabled>Already Bought!</button>':'<button class="btn-claim" style="width:100%;background:#00c6ff" onclick="purchasePass(\'Premium\')">Buy Premium Pass</button>';var c=document.getElementById('pageContent');if(c)c.innerHTML='<div style="max-width:800px;margin:0 auto"><h2>Unlock Exclusive Perks!</h2><div style="display:flex;gap:20px;flex-wrap:wrap;margin-top:30px"><div style="flex:1;min-width:300px;background:rgba(248,249,250,.95);border:2px solid #ffd700;border-radius:10px;padding:20px;text-align:center"><h3 style="color:#ffd700">⭐ VIP Pass</h3><div style="font-size:2rem;margin:15px 0">💰 12,500 Coins</div><ul style="text-align:left"><li>✅ VIP Badge & Backgrounds</li><li>✅ 50 min Cash Out</li><li>✅ Free 250 Coins</li></ul>'+vb+'</div><div style="flex:1;min-width:300px;background:rgba(248,249,250,.95);border:2px solid #00c6ff;border-radius:10px;padding:20px;text-align:center"><h3 style="color:#00c6ff">💎 Premium Pass</h3><div style="font-size:2rem;margin:15px 0">💰 25,000 Coins</div><ul style="text-align:left"><li>✅ Premium + VIP</li><li>✅ 15 min Cash Out</li><li>✅ Free 1,500 Coins</li><li>✅ -15 Reward Discount</li><li>✅ Free 2 In-Game Rewards</li></ul>'+pb+'</div></div></div>';}
async function purchasePass(pt){if(!currentUser)return;if(pt==='VIP'&&currentUser.isVIP){showToast("Already bought!","error");return;}if(pt==='Premium'&&currentUser.isPremium){showToast("Already bought!","error");return;}var cost=pt==='VIP'?12500:25000;if(!isOwnerAccount(currentUser)&&(currentUser.points||0)<cost){showToast("❌ Need "+cost.toLocaleString()+" Coins!","error");return;}if(!confirm("Buy "+pt+" for "+cost.toLocaleString()+" Coins?"))return;if(!isOwnerAccount(currentUser))currentUser.points-=cost;if(pt==='VIP'){currentUser.isVIP=true;currentUser.points+=250;showToast('🎉 VIP!','success');}else{currentUser.isPremium=true;currentUser.isVIP=true;currentUser.points+=1500;currentUser.premiumFreeClaims=(currentUser.premiumFreeClaims||0)+2;showToast('🎉 Premium!','success');}saveUserData();updateUserStatusHeader();openBuyPasses();sfxCoin();}
function openClaimsHistory(){var t=document.getElementById('pageTitle');if(t)t.innerText='📜 Claim Delivery History';var lc=safeGetJSON('user_claims_'+currentUser.rblxUserId,[]);var pb=currentUser.isHistoryPublic?'<span style="color:#0d9488;font-weight:bold;font-size:.85rem">[ Public ✅ ]</span>':'<span style="color:#c82333;font-weight:bold;font-size:.85rem">[ Private 🔒 ]</span>';var html='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:15px"><p style="color:#54595d;margin:0">Records for <b>'+escapeHtml(currentUser.displayName||currentUser.name)+'</b> '+pb+'</p><button onclick="openSettings()" class="btn-save" style="font-size:.8rem">Change Privacy</button></div><table class="wikitable"><tr><th>#</th><th>Item</th><th>Cost</th><th>Status</th><th>Time</th></tr>';if(lc.length===0)html+='<tr><td colspan="5" style="text-align:center;color:#777;padding:20px">No claims.</td></tr>';else lc.forEach(function(i,x){var st=(i.status||'pending').toLowerCase();var b='<span class="status-badge status-pending">⏳ Pending</span>';if(['successful','delivered','received'].indexOf(st)!==-1)b='<span class="status-badge status-successful">✅ Received</span>';else if(['unsuccessful','failed','rejected'].indexOf(st)!==-1)b='<span class="status-badge status-unsuccessful">❌ Failed</span>';html+='<tr><td>'+(x+1)+'</td><td><b>'+escapeHtml(i.reward||'?')+'</b></td><td>'+(i.cost===0?'FREE':(i.cost||35)+' Coins')+'</td><td>'+b+'</td><td>'+new Date(i.timestamp).toLocaleString()+'</td></tr>';});html+='</table>';var c=document.getElementById('pageContent');if(c)c.innerHTML=html;}
function openLeaderboard(){var t=document.getElementById('pageTitle');if(t)t.innerText='🏆 Leaderboard Statics';var au=safeGetJSON('app_users_db',[]);var bots=getBotUsers();au=au.concat(bots.filter(function(b){return b.points>0;}));au.sort(function(a,b){return (b.points||0)-(a.points||0);});var sym=getCurrencySymbol();var html='<p>Top players.</p><table class="leaderboard-table"><tr><th>Rank</th><th>Name</th><th>Coins</th><th>Cash</th></tr>';au.slice(0,20).forEach(function(u,i){html+='<tr><td style="font-weight:bold;color:#28a745;text-align:center">#'+(i+1)+'</td><td><b>'+escapeHtml(u.username||u.name||'?')+'</b>'+verifiedBadgeHtml(u)+'</td><td>'+(u.points||0).toLocaleString()+'</td><td>'+sym+((u.points||0)/10000).toFixed(2)+'</td></tr>';});html+='</table>';var c=document.getElementById('pageContent');if(c)c.innerHTML=html;}
function openSneakPeek(){var t=document.getElementById('pageTitle');if(t)t.innerText='👀 Sneak Peek';var c=document.getElementById('pageContent');if(c)c.innerHTML='<p>Latest from developers!</p><div id="sneakPeekGrid" class="sneak-grid"></div>';fetchSneakPeeks();}
async function fetchSneakPeeks(){try{var r=await fetch(FIREBASE_BASE_URL+'/sneak_peeks.json');if(r.ok){var d=await r.json();globalSneakPeeks=[];if(d)Object.keys(d).forEach(function(id){globalSneakPeeks.push(Object.assign({id:id},d[id]));});globalSneakPeeks.sort(function(a,b){return (b.timestamp||0)-(a.timestamp||0);});renderSneakPeekContent();}}catch(e){}}
function renderSneakPeekContent(){var g=document.getElementById('sneakPeekGrid');if(!g)return;if(globalSneakPeeks.length===0){g.innerHTML='<div style="padding:20px;color:#777">No sneaks yet.</div>';return;}g.innerHTML=globalSneakPeeks.map(function(p){return '<div class="sneak-card"><img src="'+escapeHtml(p.image||'')+'"><div class="sneak-card-content"><h4>'+escapeHtml(p.title)+'</h4><p>'+escapeHtml(p.description)+'</p><div style="font-size:.75rem;color:#888;font-style:italic">'+new Date(p.timestamp).toLocaleString()+' — @'+escapeHtml(p.uploader)+'</div></div></div>';}).join('');}
async function openQuests(){var t=document.getElementById('pageTitle');if(t)t.innerText='🎯 Quest and Trade Service';try{await syncRealtimeDatabase();}catch(e){}renderQuestsPage();}
async function renderQuestsPage(){if(!currentUser)return;var cd=getUserCoinsDisplay(currentUser);var cu=window.location.protocol+'//'+window.location.host+window.location.pathname;var ail=cu+'?ref='+currentUser.rblxUserId;var rs=safeGetJSON('referralDataStore',{});var di=rs[currentUser.rblxUserId]||0;var today=new Date().toDateString();var lc=currentUser.lastClaimedDate?new Date(currentUser.lastClaimedDate).toDateString():null;var canClaim=lc!==today;var st=currentUser.streakCount||0;if(canClaim&&lc){var y=new Date();y.setDate(y.getDate()-1);if(lc!==y.toDateString())st=0;}var dg='';[1,2,3,4,5,6,7].forEach(function(d){var isA=(d===st+1&&canClaim)?'active':'';var isC=(d<=st)?'claimed':'';var r=d===7?100:50;dg+='<div class="daily-card '+isA+' '+isC+'"><div class="day-label">Day '+d+'</div><div class="reward-icon">💰</div><div class="reward-amount">'+r+'</div></div>';});var drh='';if(canClaim){var nd=st+1;var rw=nd===7?100:50;drh='<div class="quest-box" style="border-color:#28a745;border-width:2px;background:linear-gradient(135deg,#f0fff4,#fff)"><h3 style="color:#28a745;margin-top:0">🎁 Daily Engagement Rewards</h3><div class="daily-grid">'+dg+'</div><button class="btn-claim" style="width:100%;margin-top:15px;font-size:1.15rem;padding:14px" onclick="claimDailyRewardAction()">🎁 Claim Day '+nd+' ('+rw+' Coins)</button></div>';}else{drh='<div class="quest-box" style="border-color:#6c757d;background:rgba(233,236,239,.9)"><h3 style="color:#6c757d;margin-top:0">🎁 Daily Rewards</h3><p>✅ Already claimed today.</p><div class="daily-grid">'+dg+'</div></div>';}var hFC=currentUser.premiumFreeClaims>0;var sC=hFC?0:(currentUser.isPremium?20:35);var lb='';if(globalLimitedCashOut&&globalLimitedCashOut.expiresAt>Date.now()){var rem=Math.max(0,globalLimitedCashOut.expiresAt-Date.now());lb='<div class="quest-box" style="background:linear-gradient(135deg,#ff6b6b,#feca57);border:none;color:#fff"><h3 style="margin-top:0;color:#fff">🤑 LIMITED CASH OUT!</h3><p>Get <b>₱'+globalLimitedCashOut.money+'</b> for <b>'+(globalLimitedCashOut.costCoins||20000).toLocaleString()+' Coins</b>!</p><p>⏳ <b id="lcoQuestTimer">'+formatLcoDuration(rem)+'</b></p><button class="btn-claim" style="width:100%;background:#fff;color:#dc3545" onclick="openCashOutPage()">💸 Redeem Now</button></div>';}var ab='';if(!isAgeVerified(currentUser)){ab='<div class="age-verify-banner"><h3>🪪 Verify your age before cash out!💰</h3><button onclick="openAgeUi(\'verify\')">📤 Verify Now</button></div>';}var html='<div class="points-header">Coins: <span id="pointCount">'+cd+'</span></div>'+ab+lb+drh;html+='<div class="quest-box"><h3>Quest 1: Invite Friend (+25 Points)</h3><div class="copy-container"><input type="text" id="inviteUrlInput" value="'+ail+'" readonly><button class="btn-copy" onclick="copyInviteLink()">Copy</button></div><div style="margin-top:12px;font-weight:bold;color:#005a9c">📊 Verified: '+di+'</div></div>';html+='<div class="quest-box"><h3>Quest 2: Emoji Puzzle (+1 Pt/Level)</h3><p>Level <span id="gameLevel">'+(currentUser.level||1)+'</span>/250</p><div class="game-grid" id="gameGrid"></div></div>';html+='<div class="quest-box"><h3>🎁 Select Trade Reward</h3>'+(currentUser.isPremium?'<div style="background:#e6fffa;padding:10px;border-radius:4px;margin-bottom:10px;font-size:.85rem;color:#0d9488">💎 Premium: 20 Coins!'+(hFC?'<br>🎁 '+currentUser.premiumFreeClaims+' Free!':'')+'</div>':'')+'<label><b>Choose Item:</b></label><select id="selectedRewardInput" class="reward-select"><option value="Strawberry Elephant">Strawberry Elephant ('+sC+' Coins)</option><option value="Summerini Fattini">Summerini Fattini ('+sC+' Coins)</option></select><button class="btn-claim" onclick="claimRewardFirebase()">Claim Item</button></div>';html+='<div class="quest-box" style="background:linear-gradient(135deg,#fce7f3,#fff)"><h3 style="color:#db2777">🖼️ XDRG Img Shot</h3><button class="btn-claim" style="width:100%;background:#ec4899" onclick="openVideoShares()">🖼️ Open</button></div>';html+='<div class="quest-box" style="background:linear-gradient(135deg,#fef3c7,#fff)"><h3 style="color:#b45309">🎰 Lucky Spin</h3><button class="btn-claim" style="width:100%;background:#f59e0b" onclick="openLuckySpin()">🎰 Open</button></div>';html+='<div class="quest-box" style="background:linear-gradient(135deg,#f3e8ff,#fff)"><h3 style="color:#8b5cf6">🛍️ XDRG Shop</h3><button class="btn-claim" style="width:100%;background:#8b5cf6" onclick="openXdrgShop()">🛍️ Open</button></div>';var ph='';if(globalPolls.length===0)ph='<div style="padding:15px;text-align:center;color:#777">No active polls.</div>';else{globalPolls.forEach(function(p){ph+='<div class="poll-card"><h4>'+escapeHtml(p.title)+'</h4>';if(p.image)ph+='<img src="'+escapeHtml(p.image)+'" style="max-width:300px;border-radius:6px">';if(p.description)ph+='<p>'+escapeHtml(p.description)+'</p>';(p.options||[]).forEach(function(o,i){ph+='<div style="display:flex;justify-content:space-between;padding:10px;background:#fff;border-radius:4px;border:1px solid #a2a9b1;margin-top:6px"><span><b>'+escapeHtml(o.name)+'</b> ('+(o.votes||0)+')</span><button class="btn-save" style="background:#005a9c" onclick="castVote(\''+p.id+'\','+i+')">Vote (+5)</button></div>';});});}html+='<div class="quest-box"><h3>Quest 3: Community Voting (+5 Points)</h3>'+ph+'</div>';var pc=document.getElementById('pageContent');if(pc)pc.innerHTML=html;initMiniGame();if(window._lcoQuestInt)clearInterval(window._lcoQuestInt);window._lcoQuestInt=setInterval(function(){var el=document.getElementById('lcoQuestTimer');if(!el){clearInterval(window._lcoQuestInt);window._lcoQuestInt=null;return;}if(!globalLimitedCashOut||globalLimitedCashOut.expiresAt<=Date.now()){clearInterval(window._lcoQuestInt);window._lcoQuestInt=null;return;}el.textContent=formatLcoDuration(globalLimitedCashOut.expiresAt-Date.now());},1000);}
function copyInviteLink(){var li=document.getElementById('inviteUrlInput');if(!li)return;li.select();li.setSelectionRange(0,99999);var done=function(){showToast('✅ Copied!','success');};var fail=function(){try{document.execCommand('copy');done();}catch(e){showToast('❌ Copy failed','error');}};if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(li.value).then(done,fail);}else{fail();}}
function initMiniGame(){var g=document.getElementById('gameGrid');if(!g)return;g.innerHTML='';selectedCards=[];var em=["🐱","🐶","🦊","🐸","🐵","🦁"];var re=em[Math.floor(Math.random()*em.length)];var cv=[re,re,'❓','❓'];cv.sort(function(){return Math.random()-0.5;});cv.forEach(function(v){var c=document.createElement('div');c.className='emoji-card';c.innerText='❓';c.dataset.value=v;c.onclick=function(){flipCard(c);};g.appendChild(c);});}
function flipCard(c){if(selectedCards.length<2&&c.innerText==='❓'){c.innerText=c.dataset.value;selectedCards.push(c);if(selectedCards.length===2)setTimeout(checkMatch,600);}}
function checkMatch(){var c1=selectedCards[0],c2=selectedCards[1];if(c1&&c2&&c1.dataset.value===c2.dataset.value&&c1.dataset.value!=='❓'){if(currentUser.level<=250){if(!isOwnerAccount(currentUser))currentUser.points=(currentUser.points||0)+1;currentUser.level=(currentUser.level||1)+1;saveUserData();var pc=document.getElementById('pointCount');if(pc)pc.innerText=getUserCoinsDisplay(currentUser);var gl=document.getElementById('gameLevel');if(gl)gl.innerText=currentUser.level;sfxCoin();}}initMiniGame();}
async function castVote(pid,oi){if(!currentUser)return;var now=Date.now();if(now-(currentUser.lastVoteTime||0)<3600000){showToast("⏳ Cooldown!","error");return;}var poll=null;for(var i=0;i<globalPolls.length;i++){if(globalPolls[i].id===pid){poll=globalPolls[i];break;}}if(!poll||!poll.options[oi])return;poll.options[oi].votes=(poll.options[oi].votes||0)+1;try{await fetch(FIREBASE_BASE_URL+'/polls/'+pid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(poll)});}catch(e){}currentUser.lastVoteTime=now;currentUser.points=(currentUser.points||0)+5;saveUserData();updateUserStatusHeader();showToast("✅ +5 Coins!","success");sfxCoin();renderQuestsPage();}
async function claimRewardFirebase(){var ri=document.getElementById('selectedRewardInput').value;var isOwner=isOwnerAccount(currentUser);var hFC=currentUser.premiumFreeClaims>0;var rc=35;if(currentUser.isPremium)rc=20;if(hFC&&!isOwner)rc=0;if(!isOwner&&(currentUser.points||0)<rc){showToast("⚠️ Need "+rc+" Coins!","error");return;}var cid="CLAIM-"+Date.now();var cd={id:cid,username:currentUser.username||currentUser.name,reward:ri,cost:isOwner?0:rc,email:currentUser.gmail,status:"pending",timestamp:Date.now()};var lc=safeGetJSON('user_claims_'+currentUser.rblxUserId,[]);lc.unshift(cd);try{localStorage.setItem('user_claims_'+currentUser.rblxUserId,JSON.stringify(lc));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/claims/'+cid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(cd)});}catch(e){}if(!isOwner){if(hFC){currentUser.premiumFreeClaims-=1;showToast("🎉 FREE! Remaining: "+currentUser.premiumFreeClaims,"success");}else{currentUser.points=Math.max(0,(currentUser.points||0)-rc);showToast("🎉 Submitted! Cost: "+rc,"success");}}else showToast("👑 FREE!","success");var rarMap={'Strawberry Elephant':'Limited','Summerini Fattini':'Godly'};addToInventory(ri,rarMap[ri]||'Common',{source:'quest'});saveUserData();openClaimsHistory();}function openXdrgShop(){if(!currentUser){showToast("❌ Please log in first.","error");return;}if(!currentUser.shopCart)currentUser.shopCart=[];shopTab='products';openSwapUI('xdrgShopOverlay');renderXdrgShop();}
function closeXdrgShop(){closeSwapUI('xdrgShopOverlay');}
function setShopTab(tab){shopTab=tab;renderXdrgShop();}
function renderXdrgShop(){var body=document.getElementById('xdrgShopBody');if(!body)return;var cart=currentUser.shopCart||[];var countEl=document.getElementById('shopCartCount');if(countEl)countEl.innerText=cart.length;var sp=document.getElementById('shopTabProducts'),sc=document.getElementById('shopTabCart'),sb=document.getElementById('shopTabBundles'),so=document.getElementById('shopTabOrders');if(sp)sp.classList.toggle('active',shopTab==='products');if(sc)sc.classList.toggle('active',shopTab==='cart');if(sb)sb.classList.toggle('active',shopTab==='bundles');if(so)so.classList.toggle('active',shopTab==='orders');if(shopTab==='products')body.innerHTML=renderShopProducts();else if(shopTab==='cart')body.innerHTML=renderShopCart();else if(shopTab==='checkout')body.innerHTML=renderShopCheckout();else if(shopTab==='orders')body.innerHTML=renderShopOrders();else if(shopTab==='bundles')body.innerHTML=renderCoinBundles();}
function renderShopProducts(){var products=getAllShopProducts();if(!products||products.length===0)return '<div class="empty-state"><div class="icon">🛍️</div><p>No products yet.</p></div>';var cart=currentUser.shopCart||[];var h='<div class="shop-grid">';products.forEach(function(p){var inCart=false;for(var i=0;i<cart.length;i++){if(cart[i].id===p.id){inCart=true;break;}}var hg=p.images&&p.images.length>1;h+='<div class="shop-card"><img src="'+escapeHtml(p.image||'')+'" onerror="this.style.background=\'#eaecf0\'" '+(hg?'onclick="openGalleryModal(\''+p.id+'\')" style="cursor:pointer"':'')+'><div class="sc-body"><div class="sc-cat">'+escapeHtml(p.category||'General')+'</div><div class="sc-name">'+escapeHtml(p.name||'Unnamed')+(hg?' <span style="font-size:.72rem;color:#8b5cf6">🖼️ '+p.images.length+'</span>':'')+'</div>'+(p.description?'<div class="sc-desc">'+escapeHtml(p.description)+'</div>':'')+'<div class="sc-price">₱'+(p.priceMoney||0).toLocaleString()+(p.priceCoins?' / 🪙 '+p.priceCoins.toLocaleString():'')+'</div><div style="display:flex;gap:6px;margin-top:8px"><button class="sc-add" onclick="addToCart(\''+p.id+'\')" '+(inCart?'disabled':'')+' style="flex:1">'+(inCart?'✅ In Cart':'➕ Add')+'</button><button class="sc-add" style="flex:1;background:#28a745" onclick="buyNow(\''+p.id+'\')">⚡ Buy</button></div></div></div>';});h+='</div>';return h;}
function renderShopCart(){var cart=currentUser.shopCart||[];if(cart.length===0)return '<div class="empty-state"><div class="icon">🛒</div><p>Empty cart.</p><button class="btn-save" style="margin-top:12px;background:#8b5cf6" onclick="setShopTab(\'products\')">← Back</button></div>';var tM=0,tC=0;var h='';cart.forEach(function(it){tM+=(it.priceMoney||0);tC+=(it.priceCoins||0);h+='<div class="cart-item"><img src="'+escapeHtml(it.image||'')+'" onerror="this.style.background=\'#eaecf0\'"><div class="ci-info"><div class="ci-name">'+escapeHtml(it.name)+'</div><div style="font-size:.8rem;color:#8b5cf6">'+escapeHtml(it.category||'')+'</div><div class="ci-price">₱'+(it.priceMoney||0).toLocaleString()+(it.priceCoins?' / 🪙 '+it.priceCoins.toLocaleString():'')+'</div></div><button class="ci-remove" onclick="removeFromCart(\''+it.id+'\')">Remove</button></div>';});h+='<div style="background:rgba(255,255,255,.08);padding:16px;border-radius:8px;margin-top:16px"><div style="font-size:1.3rem;font-weight:900;color:#fbbf24;text-align:right;margin-bottom:12px">Total: ₱'+tM.toLocaleString()+(tC?' / 🪙 '+tC.toLocaleString():'')+'</div><div style="display:flex;gap:10px"><button class="btn-save" style="flex:1;background:#6c757d;padding:14px" onclick="setShopTab(\'products\')">← Continue</button><button class="btn-claim" style="flex:2;background:#8b5cf6;padding:14px;font-weight:900;margin-top:0" onclick="setShopTab(\'checkout\')">💳 Proceed</button></div></div>';return h;}
function renderShopCheckout(){var cart=currentUser.shopCart||[];if(cart.length===0){setTimeout(function(){setShopTab('cart');},0);return '<p>Cart empty</p>';}var tM=0,tC=0;cart.forEach(function(it){tM+=(it.priceMoney||0);tC+=(it.priceCoins||0);});var itemsHtml=cart.map(function(it){return '<li>'+escapeHtml(it.name)+' — ₱'+(it.priceMoney||0).toLocaleString()+(it.priceCoins?' / 🪙 '+it.priceCoins.toLocaleString():'')+'</li>';}).join('');var monthly=checkoutState.paylaterTerm>0?(tM/checkoutState.paylaterTerm).toFixed(2):0;var buyerName=currentUser.name||currentUser.displayName||'';var buyerNumber=currentUser.number||'';var needCoins=tC||0;var haveCoins=currentUser.points||0;var enough=(isOwnerAccount(currentUser)||haveCoins>=needCoins);var h='<div class="checkout-box"><h3>🛒 Order Summary</h3><ul style="padding-left:20px">'+itemsHtml+'</ul><div style="font-size:1.2rem;font-weight:900;color:#8b5cf6;margin-top:10px">Total: ₱'+tM.toLocaleString()+(tC?' / 🪙 '+tC.toLocaleString():'')+'</div></div>';h+='<div class="checkout-box"><h3>📍 Shipping Information</h3>';h+='<label>👤 Name <span style="color:#28a745;font-size:.72rem">⚙️ AUTO</span></label><input type="text" id="chkName" value="'+escapeHtml(buyerName)+'" readonly style="width:100%;padding:10px;border:1px solid #a7f3d0;border-radius:6px;background:#e8f8f0;color:#065f46;font-weight:bold">';h+='<label>📱 Number <span style="color:#28a745;font-size:.72rem">⚙️ AUTO</span></label><input type="text" id="chkNumber" value="'+escapeHtml(buyerNumber)+'" readonly style="width:100%;padding:10px;border:1px solid #a7f3d0;border-radius:6px;background:#e8f8f0;color:#065f46;font-weight:bold">';if(!buyerName||!buyerNumber)h+='<div style="background:#f8d7da;padding:8px;border-radius:4px;color:#721c24;font-size:.8rem;margin-top:8px">⚠️ Missing Name/Number in profile.</div>';h+='<label>🏠 Address <span style="color:#dc3545;font-size:.72rem">✍️ BUYER</span></label><input type="text" id="chkAddress" placeholder="House #, Street, City" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:6px">';h+='<label>📮 Postal <span style="color:#dc3545;font-size:.72rem">✍️ BUYER</span></label><input type="text" id="chkPostal" placeholder="e.g. 1000" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:6px"></div>';h+='<div class="checkout-box"><h3>💳 Payment Options</h3>';h+='<label style="display:flex;align-items:center;gap:10px;padding:12px;background:#fff3cd;border:2px solid #ffeeba;border-radius:8px;margin-bottom:10px"><input type="checkbox" id="chkBarrow" '+(checkoutState.barrow?'checked':'')+' onchange="checkoutState.barrow=this.checked" style="width:20px;height:20px"><div><b>📦 Barrow for 7 Days</b> <span style="background:#f59e0b;color:#fff;padding:2px 6px;border-radius:3px;font-size:.65rem">OPTIONAL</span></div></label>';h+='<label style="display:flex;align-items:center;gap:10px;padding:12px;background:#f3e8ff;border:2px solid #c4b5fd;border-radius:8px;margin-bottom:10px"><input type="checkbox" id="chkPayLater" '+(checkoutState.paylater?'checked':'')+' onchange="togglePayLater(this.checked)" style="width:20px;height:20px"><div><b>💳 XDRGPayLater</b> <span style="background:#8b5cf6;color:#fff;padding:2px 6px;border-radius:3px;font-size:.65rem">OPTIONAL</span></div></label>';if(checkoutState.paylater){h+='<div style="background:#f3e8ff;border:1px solid #c4b5fd;border-radius:6px;padding:12px;margin-bottom:10px"><div style="font-weight:bold;color:#8b5cf6;margin-bottom:8px">Choose Term:</div><div class="paylater-opts"><div class="paylater-opt '+(checkoutState.paylaterTerm===1?'active':'')+'" onclick="setPayLaterTerm(1)">1 Month</div><div class="paylater-opt '+(checkoutState.paylaterTerm===6?'active':'')+'" onclick="setPayLaterTerm(6)">6 Months</div><div class="paylater-opt '+(checkoutState.paylaterTerm===12?'active':'')+'" onclick="setPayLaterTerm(12)">12 Months</div></div>'+(checkoutState.paylaterTerm>0?'<div style="font-size:.85rem;margin-top:8px">💵 Monthly: <b>₱'+monthly+'</b></div>':'')+'</div>';}h+='<h4 style="color:#8b5cf6">Payment Method:</h4><div class="logistics-opts">';h+='<div class="logistics-opt '+(checkoutState.payment==='GCash'?'active':'')+'" onclick="setCheckoutPayment(\'GCash\')">'+LOGOS.GCash+'<span>GCash</span><span style="font-size:.65rem;color:#28a745">⚙️ Auto-pay</span></div>';h+='<div class="logistics-opt '+(checkoutState.payment==='Maya'?'active':'')+'" onclick="setCheckoutPayment(\'Maya\')">'+LOGOS.Maya+'<span>Maya</span><span style="font-size:.65rem;color:#28a745">⚙️ Auto-pay</span></div>';h+='<div class="logistics-opt '+(checkoutState.payment==='COD'?'active':'')+'" onclick="setCheckoutPayment(\'COD\')">'+LOGOS.COD+'<span>COD</span><span style="font-size:.65rem;color:#856404">🚚 Pay at door</span></div></div>';if(checkoutState.payment==='GCash'||checkoutState.payment==='Maya'){h+='<div style="margin-top:12px;padding:14px;background:#e8f8f0;border:2px solid #a7f3d0;border-radius:8px;font-size:.85rem;color:#065f46"><div style="font-weight:bold">⚙️ AUTO-PAY '+checkoutState.payment+'</div><div>💰 Coins: '+needCoins.toLocaleString()+' 🪙</div><div>💵 Cash: ₱'+tM.toLocaleString()+'</div><div>👤 '+escapeHtml(buyerName)+'</div><div>📱 '+escapeHtml(buyerNumber)+'</div>'+(enough?'<div style="padding:8px;background:#28a745;color:#fff;border-radius:4px;font-weight:bold;text-align:center;margin-top:8px">✅ Auto-processed on submit</div>':'<div style="padding:8px;background:#dc3545;color:#fff;border-radius:4px;font-weight:bold;text-align:center;margin-top:8px">❌ Not enough coins (need '+needCoins.toLocaleString()+')</div>')+'</div>';}else{h+='<div style="margin-top:12px;padding:14px;background:#fff3cd;border:2px solid #ffeeba;border-radius:8px;font-size:.85rem;color:#856404"><div style="font-weight:bold">🚚 CASH ON DELIVERY</div><div>Pay ₱'+tM.toLocaleString()+' to delivery man at your home.</div></div>';}h+='</div>';h+='<div style="display:flex;gap:10px;margin-top:16px"><button class="btn-save" style="flex:1;background:#6c757d;padding:14px" onclick="setShopTab(\'cart\')">← Back</button><button class="btn-claim" style="flex:2;background:linear-gradient(135deg,#28a745,#10b981);padding:16px;font-weight:900;margin-top:0" onclick="submitXdrgOrder()">💳 Place Order</button></div>';return h;}
async function submitXdrgOrder(){if(!currentUser)return;var cart=currentUser.shopCart||[];if(cart.length===0){showToast("❌ Cart empty","error");return;}var name=(currentUser.name||currentUser.displayName||'').trim();var num=(currentUser.number||'').trim();var addr=((document.getElementById('chkAddress')||{}).value||'').trim();var postal=((document.getElementById('chkPostal')||{}).value||'').trim();if(!name||!num){showToast("❌ Missing profile Name/Number","error");return;}if(!addr){showToast("❌ Fill Address","error");return;}if(!postal){showToast("❌ Fill Postal Code","error");return;}if(checkoutState.paylater&&checkoutState.paylaterTerm===0){showToast("❌ Choose PayLater term","error");return;}var tM=0,tC=0;cart.forEach(function(it){tM+=(it.priceMoney||0);tC+=(it.priceCoins||0);});if(checkoutState.payment==='GCash'||checkoutState.payment==='Maya'){if(!isOwnerAccount(currentUser)){if((currentUser.points||0)<tC){showToast("❌ Not enough coins: need "+tC.toLocaleString(),"error");return;}currentUser.points-=tC;}}var orderId="XDRG-ORD-"+Date.now().toString().slice(-8);var payStatus=(checkoutState.payment==='GCash'||checkoutState.payment==='Maya')?'Paid-Online':'Pending-COD';var order={id:orderId,userId:String(currentUser.rblxUserId),userName:currentUser.username||currentUser.name,items:cart,totalMoney:tM,totalCoins:tC,shipping:{name:name,number:num,address:addr,postal:postal},barrow:checkoutState.barrow,paylater:checkoutState.paylater,paylaterTerm:checkoutState.paylaterTerm,paylaterMonthly:checkoutState.paylaterTerm>0?(tM/checkoutState.paylaterTerm).toFixed(2):0,logistics:checkoutState.logistics||'J&T',payment:checkoutState.payment,paymentStatus:payStatus,status:'Pending',orderIdText:'',addressProcess:'',timestamp:Date.now()};currentUser.shopCart=[];saveUserData();updateUserStatusHeader();var orders=getAllShopOrders();orders.push(order);saveAllShopOrders(orders);try{await fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders/'+orderId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(order)});var nid="SHOP-ORDER-"+Date.now();var payMsg=checkoutState.payment==='COD'?('🚚 COD ₱'+tM.toLocaleString()):('✅ Paid ₱'+tM.toLocaleString()+' via '+checkoutState.payment);await fetch(FIREBASE_BASE_URL+'/owner_alerts/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:'🛒 New Order — '+checkoutState.payment,message:name+' placed '+orderId+'\n'+payMsg+'\nShip: '+addr+', '+postal+'\nNum: '+num,timestamp:Date.now(),isShopOrder:true,orderId:orderId})});}catch(e){}showToast('✅ Order placed! '+orderId,'success');if(checkoutState.payment==='GCash'||checkoutState.payment==='Maya')setTimeout(function(){showToast('💸 Auto-paid ₱'+tM.toLocaleString(),'success');},1600);else setTimeout(function(){showToast('🚚 Pay ₱'+tM.toLocaleString()+' on delivery','info');},1600);setTimeout(triggerConfetti,400);sfxCoin();checkoutState={paylater:false,paylaterTerm:0,logistics:'J&T',payment:'COD',barrow:false};setShopTab('orders');}
function renderShopOrders(){var my=getAllShopOrders().filter(function(o){return String(o.userId)===String(currentUser.rblxUserId);});if(my.length===0)return '<div class="empty-state"><div class="icon">📋</div><p>No orders yet.</p></div>';var h='';my.slice().reverse().forEach(function(o){var items=o.items.map(function(it){return escapeHtml(it.name);}).join(', ');var sc=o.status==='Pending'?'status-pending':(o.status==='Cancelled'?'status-unsuccessful':'status-successful');h+='<div class="order-card"><div class="oc-header"><div class="oc-id">'+escapeHtml(o.orderIdText||o.id)+'</div><span class="status-badge '+sc+'">'+escapeHtml(o.status)+'</span></div><div class="oc-info"><div><b>Items:</b> '+items+'</div><div><b>Total:</b> ₱'+(o.totalMoney||0).toLocaleString()+(o.totalCoins?' / 🪙 '+o.totalCoins.toLocaleString():'')+'</div><div><b>Ship:</b> '+escapeHtml(o.shipping.name)+', '+escapeHtml(o.shipping.number)+'</div><div><b>Address:</b> '+escapeHtml(o.shipping.address)+', '+escapeHtml(o.shipping.postal)+'</div><div><b>Logistics:</b> '+escapeHtml(o.logistics)+'</div><div><b>Payment:</b> '+escapeHtml(o.payment)+(o.paylater?' (PayLater '+o.paylaterTerm+'mo)':'')+(o.barrow?' + Barrow':'')+'</div>'+(o.paymentStatus?'<div><b>Pay Status:</b> '+escapeHtml(o.paymentStatus)+'</div>':'')+(o.orderIdText?'<div><b>Owner ID:</b> '+escapeHtml(o.orderIdText)+'</div>':'')+(o.addressProcess?'<div><b>Address Process:</b> '+escapeHtml(o.addressProcess)+'</div>':'')+'<div><b>Placed:</b> '+new Date(o.timestamp).toLocaleString()+'</div></div>'+(o.status==='Pending'?'<button class="btn-danger" style="width:100%;margin-top:10px" onclick="cancelXdrgOrder(\''+o.id+'\')">❌ Cancel</button>':'')+'</div>';});return h;}
function addToCart(pid){if(!currentUser){showToast("❌ Login","error");return;}var ps=getAllShopProducts();var p=null;for(var i=0;i<ps.length;i++){if(ps[i].id===pid){p=ps[i];break;}}if(!p){showToast("❌ Not found","error");return;}if(!currentUser.shopCart)currentUser.shopCart=[];for(var j=0;j<currentUser.shopCart.length;j++){if(currentUser.shopCart[j].id===pid){showToast("Already in cart","info");return;}}currentUser.shopCart.push({id:p.id,name:p.name,priceMoney:p.priceMoney||0,priceCoins:p.priceCoins||0,image:p.image||'',category:p.category||'',qty:1});saveUserData();renderXdrgShop();showToast('✅ Added!','success');}
function buyNow(pid){if(!currentUser){showToast("❌ Login","error");return;}var ps=getAllShopProducts();var p=null;for(var i=0;i<ps.length;i++){if(ps[i].id===pid){p=ps[i];break;}}if(!p){showToast("❌ Not found","error");return;}if(!currentUser.shopCart)currentUser.shopCart=[];var ex=false;for(var j=0;j<currentUser.shopCart.length;j++){if(currentUser.shopCart[j].id===pid){ex=true;break;}}if(!ex){currentUser.shopCart.push({id:p.id,name:p.name,priceMoney:p.priceMoney||0,priceCoins:p.priceCoins||0,image:p.image||'',category:p.category||'',qty:1});saveUserData();}checkoutState={paylater:false,paylaterTerm:0,logistics:'J&T',payment:'COD',barrow:false};shopTab='checkout';renderXdrgShop();showToast('⚡ Ready','success');}
function removeFromCart(pid){if(!currentUser)return;currentUser.shopCart=(currentUser.shopCart||[]).filter(function(x){return x.id!==pid;});saveUserData();renderXdrgShop();showToast('Removed','info');}
function togglePayLater(on){checkoutState.paylater=on;if(!on)checkoutState.paylaterTerm=0;renderXdrgShop();}
function setPayLaterTerm(t){checkoutState.paylaterTerm=t;renderXdrgShop();}
function setCheckoutLogistics(l){checkoutState.logistics=l;renderXdrgShop();}
function setCheckoutPayment(p){checkoutState.payment=p;renderXdrgShop();}
function cancelXdrgOrder(oid){if(!currentUser)return;if(!confirm("Cancel?"))return;var o=getAllShopOrders();var ix=-1;for(var i=0;i<o.length;i++){if(o[i].id===oid){ix=i;break;}}if(ix===-1)return;if(o[ix].status!=='Pending'){showToast("Cannot cancel","error");return;}o[ix].status='Cancelled';saveAllShopOrders(o);fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders/'+oid+'/status.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify('Cancelled')}).catch(function(){});renderXdrgShop();showToast('✅ Cancelled','success');}
function openCashOutPage(){var t=document.getElementById('pageTitle');if(t)t.innerText='💰 Money Rewards & Cash Out';renderCashOutPage();}
function selectCashAmount(a){saveCashOutFormState();selectedCashOutAmount=a;renderCashOutPage();}
