function renderCashOutPage(){if(!currentUser)return;var pc=document.getElementById('pageContent');if(!pc)return;if(!isAgeVerified(currentUser)){pc.innerHTML='<div class="cashout-card" style="max-width:600px;text-align:center;padding:40px 25px"><div style="font-size:5rem">🪪</div><h2 style="color:#8b5cf6;border:none">Verify your age before cash out!💰</h2><p>You must verify your age (13+) before you can cash out real money.</p><button class="btn-claim" style="background:#8b5cf6;padding:16px 32px" onclick="openAgeUi(\'verify\')">📤 Verify Age Now</button></div>';return;}if((currentUser.verifiedAgeValue||0)<13){pc.innerHTML='<div class="cashout-card" style="max-width:600px;text-align:center;padding:40px 25px;border-color:#dc3545"><div style="font-size:5rem">⚠️</div><h2 style="color:#dc3545;border:none">Under 13 — Cash Out Disabled</h2><p>Your verified age is <b>'+currentUser.verifiedAgeValue+'</b>.</p><button class="btn-claim" style="background:#8b5cf6" onclick="openAgeAppeal()">📩 Submit Appeal</button></div>';return;}var cfg=currencyConfig[currentLanguage]||currencyConfig['en'];var coins=currentUser.points||0;var cashBonus=currentUser.cashBalance||0;var displayEst=isOwnerAccount(currentUser)?"∞":convertCurrency(coins/10000+cashBonus);var reqCoins=selectedCashOutAmount*10000;if(cfg.paymentMethods.indexOf(selectedPaymentMethod)===-1)selectedPaymentMethod=cfg.defaultPay;var wt=currentUser.isPremium?'Premium: 15 minutes ⚡':(currentUser.isVIP?'VIP: 50 minutes ⏳':'Standard: 1-3 business days.');var popts='';cfg.paymentMethods.forEach(function(m){popts+='<div class="payment-option '+(selectedPaymentMethod===m?'active':'')+'" onclick="selectPaymentMethod(\''+m+'\')">'+getPaymentLogo(m)+'</div>';});var lockBanner='';if(currentUser.accountLockedUntil>Date.now()){var mins=Math.ceil((currentUser.accountLockedUntil-Date.now())/60000);lockBanner='<div style="background:#f8d7da;padding:12px;border-radius:6px;margin-bottom:15px;text-align:center;font-weight:bold">🔒 Disabled — '+mins+' min.<br><button class="btn-danger" style="margin-top:8px" onclick="showLockContinueModal()">Continue</button></div>';}var currencySelectHtml='<div style="margin-bottom:15px;background:#eaf3ff;border:1px solid #a7d7f9;border-radius:6px;padding:12px"><label style="font-weight:bold;display:block;margin-bottom:6px;color:#005a9c">💱 Currency</label><select onchange="setLanguage(this.value)" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:4px;background:#fff;font-weight:bold">'+Object.keys(currencyLabels).map(function(k){return '<option value="'+k+'" '+(currentLanguage===k?'selected':'')+'>'+currencyLabels[k]+'</option>';}).join('')+'</select></div>';var limitedBanner='';if(globalLimitedCashOut&&globalLimitedCashOut.expiresAt>Date.now()){var rem2=Math.max(0,globalLimitedCashOut.expiresAt-Date.now());var canRedeem=isOwnerAccount(currentUser)||(coins>=(globalLimitedCashOut.costCoins||20000));limitedBanner='<div class="limited-cashout-banner"><h3>🤑 LIMITED CASH OUT!</h3><p>Redeem <b>₱'+globalLimitedCashOut.money+'</b> for <b>'+(globalLimitedCashOut.costCoins||20000).toLocaleString()+' Coins</b>!</p><div class="lco-timer" id="lcoTimer">⏳ '+formatLcoDuration(rem2)+'</div><button class="lco-redeem" onclick="redeemLimitedCashOut()" '+(canRedeem?'':'disabled')+'>'+(canRedeem?'💸 REDEEM NOW':'❌ Not enough')+'</button></div>';}var autoOn=currentUser.automationCashOut===true;var prefillName=autoOn?(currentUser.autoCashOutName||''):(lastCashOutFormState.name||'');var prefillNum=autoOn?(currentUser.autoCashOutNumber||''):(lastCashOutFormState.num||'');var html='<div class="cashout-card"><h2 style="text-align:center;color:#005a9c;border:none">Cash Out Money Rewards</h2>'+currencySelectHtml+limitedBanner+lockBanner+'<div class="balance-box"><div>Est: '+displayEst+'</div><div>Coins: '+(isOwnerAccount(currentUser)?'Infinity ♾️':coins.toLocaleString())+'</div>'+(cashBonus>0?'<div>Spin Cash Bonus: ₱'+cashBonus.toLocaleString()+'</div>':'')+'</div>'+(autoOn?'<div style="background:#e8f8f0;padding:10px;border-radius:6px;font-size:.82rem;margin-bottom:12px;color:#065f46">⚡ Automation ON</div>':'')+'<div style="background:#fff3cd;padding:10px;border-radius:4px;font-size:.8rem;margin-bottom:15px;text-align:center">ℹ️ '+wt+'</div><label style="font-weight:bold;display:block">Select Amount:</label><div class="amount-grid"><button class="amount-btn '+(selectedCashOutAmount===3?'active':'')+'" onclick="selectCashAmount(3)">'+convertCurrency(3)+'</button><button class="amount-btn '+(selectedCashOutAmount===5?'active':'')+'" onclick="selectCashAmount(5)">'+convertCurrency(5)+'</button><button class="amount-btn '+(selectedCashOutAmount===15?'active':'')+'" onclick="selectCashAmount(15)">'+convertCurrency(15)+'</button><button class="amount-btn '+(selectedCashOutAmount===30?'active':'')+'" onclick="selectCashAmount(30)">'+convertCurrency(30)+'</button></div><label style="font-weight:bold;display:block">Select Payment:</label><div class="payment-selection">'+popts+'</div><form onsubmit="handleCashOutSubmit(event)"><label>Account Holder Name:</label><input type="text" id="cashOutName" required value="'+escapeHtml(prefillName)+'" '+(autoOn?'readonly':'')+' oninput="isUserTypingCashOut=true;saveCashOutFormState()" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:4px;margin-bottom:10px"><label>Account Number:</label><input type="text" id="cashOutNumber" required value="'+escapeHtml(prefillNum)+'" '+(autoOn?'readonly':'')+' oninput="isUserTypingCashOut=true;saveCashOutFormState()" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:4px;margin-bottom:10px"><p style="font-size:.8rem;color:#54595d">* Required: <b>'+reqCoins.toLocaleString()+' Coins</b></p><button type="submit" class="btn-claim" style="width:100%;padding:12px">Submit Request</button></form></div>';if(isOwnerOrCoOwner(currentUser)&&globalCashOuts.length>0)html+='<div style="margin-top:30px" id="ownerCashOutDashboard"></div>';pc.innerHTML=html;if(isOwnerOrCoOwner(currentUser)&&globalCashOuts.length>0)softRefreshOwnerDashboard();if(window._lcoTimerInt)clearInterval(window._lcoTimerInt);window._lcoTimerInt=setInterval(function(){var el=document.getElementById('lcoTimer');if(!el){clearInterval(window._lcoTimerInt);window._lcoTimerInt=null;return;}if(!globalLimitedCashOut||globalLimitedCashOut.expiresAt<=Date.now()){clearInterval(window._lcoTimerInt);window._lcoTimerInt=null;return;}el.textContent='⏳ '+formatLcoDuration(globalLimitedCashOut.expiresAt-Date.now());},1000);}
async function redeemLimitedCashOut(){if(!currentUser){showToast("❌ Login","error");return;}if(!canCashOut(currentUser)){showToast("❌ Verify age first.","error");openAgeUi('verify');return;}if(!globalLimitedCashOut||globalLimitedCashOut.expiresAt<=Date.now()){showToast("❌ Expired!","error");return;}var cost=globalLimitedCashOut.costCoins||20000;var money=globalLimitedCashOut.money||20;if(!isOwnerAccount(currentUser)&&(currentUser.points||0)<cost){showToast("❌ Need "+cost.toLocaleString(),"error");return;}if(!confirm("Redeem ₱"+money+"?"))return;if(!isOwnerAccount(currentUser))currentUser.points-=cost;currentUser.cashBalance=(currentUser.cashBalance||0)+money;saveUserData();updateUserStatusHeader();var cid="LIMITED-"+Date.now();var cd={id:cid,username:currentUser.username||currentUser.name,rblxUserId:currentUser.rblxUserId,amountPHP:money,provider:selectedPaymentMethod,accountName:currentUser.autoCashOutName||currentUser.name,accountNumber:currentUser.autoCashOutNumber||'TBD',requiredCoins:cost,status:"Pending",timestamp:Date.now(),isLimitedCashOut:true};try{await fetch(FIREBASE_BASE_URL+'/cashouts/'+cid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(cd)});showToast("🎉 Redeemed!","success");renderCashOutPage();}catch(e){showToast("❌ Error","error");}}
function showVerificationSelection(){var ex=document.getElementById('verifyModal');if(ex)ex.remove();var m=document.createElement('div');m.className='verify-modal';m.id='verifyModal';m.innerHTML='<div class="verify-box"><button class="verify-close-x" onclick="closeVerifyModalX()">✕</button><h3>🔐 Cash Out Verification</h3><div style="display:flex;gap:10px;margin-top:15px"><button class="btn-save" style="flex:1;padding:12px" onclick="startCodeVerification()">Code</button><button class="btn-save" style="flex:1;padding:12px;background:#6c757d" onclick="startPasswordVerification()">Password</button></div><button onclick="cancelVerification()" style="background:none;border:none;color:#721c24;cursor:pointer;text-decoration:underline;width:100%;margin-top:12px;font-weight:bold">Cancel</button></div>';document.body.appendChild(m);}
function closeVerifyModalX(){if(window._codeTimerInt){clearInterval(window._codeTimerInt);window._codeTimerInt=null;}var m=document.getElementById('verifyModal');if(m)m.remove();}
function cancelVerification(){currentVerificationCode=null;verificationCodeExpires=0;closeVerifyModalX();globalNotifications=globalNotifications.filter(function(n){return !n.isCashOutCode;});renderNotificationDropdown();showToast("Cancelled","info");}
function generateVerificationCode(){return 'xdrg'+Math.floor(100000+Math.random()*900000);}
function startCodeVerification(){var code=generateVerificationCode();currentVerificationCode=code;verificationCodeExpires=Date.now()+5*60*1000;verificationAttempts=0;globalNotifications=globalNotifications.filter(function(n){return !n.isCashOutCode;});globalNotifications.unshift({id:"CASHOUT-"+Date.now(),title:"Password Cash out Interaction",message:"Your Cash Out Verification Code (5 min):",timestamp:Date.now(),isCashOutCode:true,codeDisplay:code});renderNotificationDropdown();setTimeout(function(){var d=document.getElementById('notifDropdown');if(d)d.classList.add('active');},100);showCodeInputModal();}
function showCodeInputModal(){var o=document.getElementById('verifyModal');if(o)o.remove();var m=document.createElement('div');m.className='verify-modal';m.id='verifyModal';m.innerHTML='<div class="verify-box"><button class="verify-close-x" onclick="closeVerifyModalX()">✕</button><h3>📱 Code Verification</h3><p>Check notification 🔔</p><p style="color:#28a745;font-weight:bold" id="codeTimer">⏱️ 5:00</p><input type="text" id="verifyCodeInput" class="verify-code" maxlength="10" placeholder="xdrg000000"><p style="color:#dc3545;font-size:.8rem" id="verifyError"></p><button class="btn-claim" style="width:100%;padding:12px" onclick="submitCodeVerification()">Verify</button><div style="text-align:center;margin-top:12px"><a style="color:#005a9c;font-size:.85rem;cursor:pointer;text-decoration:underline" onclick="requestNewCode()">I don\'t receive the code</a></div><button onclick="cancelVerification()" style="background:none;border:none;color:#721c24;cursor:pointer;text-decoration:underline;width:100%;margin-top:10px;font-weight:bold">Cancel</button></div>';document.body.appendChild(m);if(window._codeTimerInt)clearInterval(window._codeTimerInt);window._codeTimerInt=setInterval(function(){var el=document.getElementById('codeTimer');if(!el){clearInterval(window._codeTimerInt);window._codeTimerInt=null;return;}var rem=Math.max(0,Math.ceil((verificationCodeExpires-Date.now())/1000));el.innerText='⏱️ '+Math.floor(rem/60)+':'+(rem%60).toString().padStart(2,'0');if(rem<=0)el.innerText='❌ Expired';},500);}
function requestNewCode(){var code=generateVerificationCode();currentVerificationCode=code;verificationCodeExpires=Date.now()+5*60*1000;globalNotifications.unshift({id:"CASHOUT-"+Date.now(),title:"Password Cash out Interaction",message:"New code (5 min):",timestamp:Date.now(),isCashOutCode:true,codeDisplay:code});renderNotificationDropdown();showToast("📬 Sent!","success");}
function reopenCodeVerification(){if(!currentVerificationCode||Date.now()>verificationCodeExpires){showToast("⚠️ No code","error");return;}showCodeInputModal();}
function automationFromNotification(code){if(currentVerificationCode!==code||Date.now()>verificationCodeExpires){showToast("⚠️ Expired","error");return;}closeVerifyModalX();var d=document.getElementById('notifDropdown');if(d)d.classList.remove('active');showToast("⚡ Automation!","success");processCashOut();}
function submitCodeVerification(){var inp=document.getElementById('verifyCodeInput');var err=document.getElementById('verifyError');var ent=inp.value.trim().toLowerCase();if(!ent){err.innerText='❌ Enter code';return;}if(Date.now()>verificationCodeExpires){err.innerText='❌ Expired';return;}if(ent!==currentVerificationCode.toLowerCase()){verificationAttempts++;err.innerText='❌ Attempts: '+verificationAttempts+'/15';inp.value='';if(verificationAttempts>=15){cancelVerification();lockAccountFor1Hour();}return;}closeVerifyModalX();processCashOut();}
function startPasswordVerification(){var o=document.getElementById('verifyModal');if(o)o.remove();var m=document.createElement('div');m.className='verify-modal';m.id='verifyModal';m.innerHTML='<div class="verify-box"><button class="verify-close-x" onclick="closeVerifyModalX()">✕</button><h3>🔑 Password Verification</h3><input type="password" id="verifyPasswordInput" class="verify-code" placeholder="Password" style="letter-spacing:normal"><p style="color:#dc3545;font-size:.8rem" id="verifyError"></p><button class="btn-claim" style="width:100%;padding:12px" onclick="submitPasswordVerification()">Verify</button><button onclick="cancelVerification()" style="background:none;border:none;color:#721c24;cursor:pointer;text-decoration:underline;width:100%;margin-top:10px;font-weight:bold">Cancel</button></div>';document.body.appendChild(m);}
function submitPasswordVerification(){var inp=document.getElementById('verifyPasswordInput');var err=document.getElementById('verifyError');if(inp.value.trim()===currentUser.password){currentUser.wrongPasswordAttempts=0;saveUserData();closeVerifyModalX();processCashOut();return;}currentUser.wrongPasswordAttempts=(currentUser.wrongPasswordAttempts||0)+1;saveUserData();err.innerText='❌ Attempts: '+currentUser.wrongPasswordAttempts+'/15';inp.value='';if(currentUser.wrongPasswordAttempts>=15){cancelVerification();lockAccountFor1Hour();}}
function lockAccountFor1Hour(){currentUser.accountLockedUntil=Date.now()+3600000;currentUser.wrongPasswordAttempts=0;saveUserData();globalNotifications.unshift({id:"LOCK-"+Date.now(),title:"Password Cash out Interaction",message:"Account disabled for 1 hour.",timestamp:Date.now(),isAccountLockNotif:true});renderNotificationDropdown();showToast("🔒 Locked 1 hour.","error");}
function showLockContinueModal(){var o=document.getElementById('verifyModal');if(o)o.remove();var m=document.createElement('div');m.className='verify-modal';m.id='verifyModal';m.innerHTML='<div class="verify-box"><button class="verify-close-x" onclick="closeVerifyModalX()">✕</button><h3>Password Cash out Interaction</h3><input type="password" id="unlockPasswordInput" class="verify-code" placeholder="Password" style="letter-spacing:normal"><p style="color:#dc3545;font-size:.8rem" id="verifyError"></p><button class="btn-save" style="width:100%;padding:12px" onclick="submitUnlockPassword()">Done</button></div>';document.body.appendChild(m);}
function submitUnlockPassword(){var inp=document.getElementById('unlockPasswordInput');var err=document.getElementById('verifyError');if(inp.value.trim()===currentUser.password){currentUser.accountLockedUntil=0;currentUser.wrongPasswordAttempts=0;saveUserData();closeVerifyModalX();globalNotifications=globalNotifications.filter(function(n){return !n.isAccountLockNotif;});renderNotificationDropdown();showToast("✅ Unlocked!","success");return;}err.innerText='❌ Incorrect';inp.value='';}
async function handleCashOutSubmit(e){e.preventDefault();if(!currentUser)return;if(!canCashOut(currentUser)){showToast("❌ Verify age first.","error");openAgeUi('verify');return;}var hn=document.getElementById('cashOutName').value.trim();var an=document.getElementById('cashOutNumber').value.trim();if(!hn||!an){showToast("❌ Fill all!","error");return;}if(currentUser.accountLockedUntil>Date.now()){showLockContinueModal();return;}pendingCashOutData={hn:hn,an:an,amt:selectedCashOutAmount,mt:selectedPaymentMethod};showVerificationSelection();}
async function processCashOut(){if(!pendingCashOutData)return;var hn=pendingCashOutData.hn,an=pendingCashOutData.an,amt=pendingCashOutData.amt,mt=pendingCashOutData.mt;var rc=amt*10000;var iO=isOwnerAccount(currentUser);if(!iO&&(currentUser.points||0)<rc){showToast("❌ Need "+rc.toLocaleString(),"error");return;}var cid="CASHOUT-"+Date.now();var cd={id:cid,username:currentUser.username||currentUser.name,rblxUserId:currentUser.rblxUserId,amountPHP:amt,provider:mt,accountName:hn,accountNumber:an,requiredCoins:rc,status:"Pending",timestamp:Date.now()};if(!iO){currentUser.points-=rc;saveUserData();updateUserStatusHeader();}try{await fetch(FIREBASE_BASE_URL+'/cashouts/'+cid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(cd)});var onid="OWNER-ALERT-"+Date.now();await fetch(FIREBASE_BASE_URL+'/owner_alerts/'+onid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:onid,title:"💰 New Cash Out",message:'@'+currentUser.username+' ₱'+amt,timestamp:Date.now()})});showToast("✅ Submitted!","success");pendingCashOutData=null;currentVerificationCode=null;globalNotifications=globalNotifications.filter(function(n){return !n.isCashOutCode;});renderNotificationDropdown();renderCashOutPage();}catch(e){showToast("❌ Error","error");}}
function softRefreshOwnerDashboard(){var g=document.getElementById('ownerCashOutDashboard');if(!g)return;var inner='<table class="wikitable"><tr><th>User</th><th>Amount</th><th>Method</th><th>Holder</th><th>Account</th><th>Status</th><th>Action</th></tr>';globalCashOuts.forEach(function(c){var sb='<span class="status-badge status-pending">'+escapeHtml(c.status||'Pending')+'</span>';var ab='';if((c.status||'').toLowerCase()==='completed'){sb='<span class="status-badge status-successful">✅ Done</span>';ab='<b style="color:#28a745">Paid</b>';}else ab='<button class="btn-action-sm" onclick="updateCashOutStatus(\''+c.id+'\',\'Completed\')">Mark Done</button>';var dA=c.amount!==undefined?c.amount:(c.amountPHP!==undefined?c.amountPHP:'N/A');inner+='<tr><td><b>'+escapeHtml(c.username||'User')+'</b></td><td>₱'+escapeHtml(String(dA))+'</td><td>'+escapeHtml(c.method||c.provider||'N/A')+'</td><td>'+escapeHtml(c.holderName||c.accountName||'N/A')+'</td><td><code>'+escapeHtml(c.accountNumber||'N/A')+'</code></td><td>'+sb+'</td><td>'+ab+'</td></tr>';});inner+='</table>';g.innerHTML=inner;}
async function updateCashOutStatus(cid,s){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;try{await fetch(FIREBASE_BASE_URL+'/cashouts/'+cid+'/status.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(s)});showToast("✅ "+s+"!","success");syncRealtimeDatabase();}catch(e){showToast("❌ Error","error");}}
