function getSpinCooldownRemaining(){var last=safeGetJSON('spin_last_'+((currentUser&&currentUser.rblxUserId)||'guest'),0);return Math.max(0,30*60*1000-(Date.now()-last));}
function formatSpinTime(ms){var s=Math.floor(ms/1000);var m=Math.floor(s/60);var sec=s%60;return String(m).padStart(2,'0')+':'+String(sec).padStart(2,'0');}
function renderLuckySpinOverlay(){var c=document.getElementById('luckySpinContent');var rem=getSpinCooldownRemaining();var hasExtra=currentUser&&(currentUser.extraSpins||0)>0;var ready=rem<=0||hasExtra;var n=SPIN_SEGMENTS.length;var sa=360/n;var conic=[];SPIN_SEGMENTS.forEach(function(s,i){conic.push(s.color+' '+(i*sa)+'deg '+((i+1)*sa)+'deg');});var lh='';SPIN_SEGMENTS.forEach(function(s,i){var a=i*sa+sa/2;lh+='<div class="spin-label" style="transform:translate(-50%,-50%) rotate('+a+'deg) translateY(-115px);"><span style="display:inline-block;transform:rotate('+(-a)+'deg);">'+s.label+'</span></div>';});var lg=SPIN_SEGMENTS.map(function(s){return '<div><span>'+s.label+'</span><small style="opacity:.7">'+s.weight+'%</small></div>';}).join('');var bl;if(ready&&hasExtra&&rem>0)bl='🎯 SPIN NOW ('+currentUser.extraSpins+' Extra)';else if(ready)bl='🎯 SPIN NOW';else bl='⏳ '+formatSpinTime(rem);c.innerHTML='<div style="text-align:center;padding:20px 0"><h2 style="color:#fbbf24;border:none;margin-bottom:8px">🎰 Lucky Spin</h2><p style="color:#94a3b8">Every 30 minutes!</p><div class="spin-wheel-box"><div class="spin-pointer">🔻</div><div class="spin-wheel" id="spinWheel" style="transform:rotate('+spinRotation+'deg);background:conic-gradient('+conic.join(',')+')">'+lh+'<div class="spin-center">SPIN</div></div></div><button class="spin-btn" id="spinBtn" '+(ready?'':'disabled')+' onclick="doLuckySpin()">'+bl+'</button><div class="spin-legend">'+lg+'</div></div>';if(!ready){if(window._spinCdInt)clearInterval(window._spinCdInt);window._spinCdInt=setInterval(function(){var b=document.getElementById('spinBtn');if(!b){clearInterval(window._spinCdInt);window._spinCdInt=null;return;}var r=getSpinCooldownRemaining();if(r<=0){b.disabled=false;b.textContent='🎯 SPIN NOW';clearInterval(window._spinCdInt);window._spinCdInt=null;}else b.textContent='⏳ '+formatSpinTime(r);},1000);}}
function doLuckySpin(){if(spinInProgress)return;var rem=getSpinCooldownRemaining();var hasExtra=currentUser&&(currentUser.extraSpins||0)>0;var useExtra=rem>0&&hasExtra;if(rem>0&&!hasExtra){showToast("⏳ Wait "+formatSpinTime(rem),"info");return;}spinInProgress=true;var b=document.getElementById('spinBtn');if(b)b.disabled=true;var tw=SPIN_SEGMENTS.reduce(function(a,s){return a+s.weight;},0);var r=Math.random()*tw;var wi=0,acc=0;for(var i=0;i<SPIN_SEGMENTS.length;i++){acc+=SPIN_SEGMENTS[i].weight;if(r<=acc){wi=i;break;}}var seg=SPIN_SEGMENTS[wi];var n=SPIN_SEGMENTS.length;var sa=360/n;var center=wi*sa+sa/2;var cm=((spinRotation%360)+360)%360;var tm=(360-center+360)%360;var delta=(tm-cm+360)%360;spinRotation+=360*5+delta;var w=document.getElementById('spinWheel');if(w)w.style.transform='rotate('+spinRotation+'deg)';setTimeout(async function(){spinInProgress=false;if(useExtra){currentUser.extraSpins=(currentUser.extraSpins||0)-1;saveUserData();}else try{localStorage.setItem('spin_last_'+((currentUser&&currentUser.rblxUserId)||'guest'),JSON.stringify(Date.now()));}catch(e){}var msg='';if(seg.vip){if(currentUser){currentUser.isVIP=true;saveUserData();updateUserStatusHeader();}msg='⭐ VIP 24h!';}else if(seg.cash){if(currentUser){currentUser.cashBalance=(currentUser.cashBalance||0)+seg.cash;saveUserData();}msg='💰 PHP ₱'+seg.cash+'!';}else if(seg.nothing){msg='😭 Nothing!';}else if(seg.extraSpins){if(currentUser){currentUser.extraSpins=(currentUser.extraSpins||0)+seg.extraSpins;saveUserData();}msg='🎉 '+seg.extraSpins+' Extra Spins!';}else if(seg.verifiedTrial){if(currentUser){currentUser.isVerified=true;currentUser.verifiedExpiry=Date.now()+30*24*3600*1000;saveUserData();updateUserStatusHeader();}msg='🔵 Verified Badge (1mo)!';}else if(seg.coins){if(currentUser){currentUser.points=(currentUser.points||0)+seg.coins;saveUserData();updateUserStatusHeader();}msg='🪙 '+seg.coins.toLocaleString()+' Coins!';}if(currentUser){var nid="SPIN-"+Date.now();globalNotifications.unshift({id:nid,title:"🎰 Lucky Spin Result",message:'You won '+msg,timestamp:Date.now()});renderNotificationDropdown();}showToast('🎉 You won: '+msg,'success');if(!seg.nothing){triggerConfetti();sfxCoin();}renderLuckySpinOverlay();},4600);}function checkDailyReward(){if(!currentUser)return;var t=new Date().toDateString();var l=currentUser.lastClaimedDate?new Date(currentUser.lastClaimedDate).toDateString():null;if(l===t)return;var s=currentUser.streakCount||0;if(l){var y=new Date();y.setDate(y.getDate()-1);s=(l===y.toDateString())?s+1:1;}else s=1;if(s>7)s=1;currentUser.streakCount=s;saveUserData();globalNotifications.unshift({id:"DAILY-"+Date.now(),title:"🎁 Daily Reward Ready!",message:"Claim now!",timestamp:Date.now(),isDailyReward:true});renderNotificationDropdown();}
function claimDailyRewardAction(){if(!currentUser)return;var t=new Date().toDateString();var l=currentUser.lastClaimedDate?new Date(currentUser.lastClaimedDate).toDateString():null;if(l===t){showToast("❌ Already claimed","error");return;}var s=currentUser.streakCount||1;var rc=s===7?100:50;if(currentUser.isPremium)rc*=3;else if(currentUser.isVIP)rc*=2;currentUser.points=(currentUser.points||0)+rc;currentUser.lastClaimedDate=new Date().toISOString();saveUserData();updateUserStatusHeader();globalNotifications=globalNotifications.filter(function(n){return !n.isDailyReward;});renderNotificationDropdown();showToast('🎉 Day '+s+'! +'+rc+' Coins!','success');triggerConfetti();sfxCoin();var pt=document.getElementById('pageTitle');if(pt&&pt.innerText.indexOf('Quest')!==-1)renderQuestsPage();}
function toggleNotifDropdown(e){e.stopPropagation();var d=document.getElementById('notifDropdown');if(d)d.classList.toggle('active');}
function renderNotificationDropdown(){var le=document.getElementById('notifList');var be=document.getElementById('notifUnreadBadge');if(!le)return;var ri=safeGetJSON('read_notif_ids',[]);var uc=0;if(globalNotifications.length===0){le.innerHTML='<li class="notif-item" style="text-align:center;color:#777;padding:15px">No notifications yet.</li>';if(be)be.style.display="none";return;}var html="";globalNotifications.forEach(function(n){var isR=ri.indexOf(n.id)!==-1;if(!isR)uc++;var ds=n.timestamp?new Date(n.timestamp).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'';var ah='';if(n.isCashOutCode)ah='<div class="notif-code-box">'+escapeHtml(n.codeDisplay||'')+'</div><button class="notif-automation-btn" onclick="automationFromNotification(\''+escapeHtml(n.codeDisplay||'')+'\')">⚡ Automation</button><button class="notif-automation-btn" style="background:#005a9c;margin-top:5px" onclick="reopenCodeVerification()">Re-open Code Entry</button>';if(n.isAccountLockNotif)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#dc3545" onclick="showLockContinueModal()">Continue</button></div>';if(n.isFriendRequest)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#0d6efd" onclick="openFriendConfirmation()">View</button></div>';if(n.isNewMessage)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#17a2b8" onclick="openMessenger(\''+escapeHtml(n.fromUserId||'')+'\')">Open Chat</button></div>';if(n.isDailyReward&&currentUser){var td=new Date().toDateString();var ld=currentUser.lastClaimedDate?new Date(currentUser.lastClaimedDate).toDateString():null;if(ld!==td)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#28a745" onclick="claimDailyRewardAction()">🎁 Claim!</button></div>';}if(n.isVerifiedBadge)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#1DA1F2" onclick="activateVerifiedBadge()">🔵 Get Badge</button></div>';if(n.isLimitedCashOut)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#f59e0b" onclick="openCashOutPage()">💸 Redeem!</button></div>';if(n.isCoinGift)ah='<div style="margin-top:6px;padding:8px;background:#e8f8f0;border-left:3px solid #28a745;border-radius:4px;font-size:.78rem;color:#155724;font-weight:bold">🪙 Coin Gift!</div>';if(n.isNewPoll)ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#005a9c" onclick="openQuests()">📊 Vote</button></div>';if(n.isAgeRequest&&currentUser&&isOwnerOrCoOwner(currentUser))ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#8b5cf6" onclick="openAgeRequest(\''+escapeHtml(n.requestId||'')+'\')">📃 Review</button></div>';if(n.isAgeAppeal&&currentUser&&isOwnerOrCoOwner(currentUser))ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#8b5cf6" onclick="openAgeRequest(\''+escapeHtml(n.requestId||'')+'\')">📃 Review</button></div>';if(n.isShopOrder&&currentUser&&isOwnerOrCoOwner(currentUser))ah='<div class="notif-actions"><button class="btn-action-sm" style="background:#8b5cf6" onclick="openStaffCommands()">🛒 View</button></div>';html+='<li class="notif-item '+(isR?'':'unread')+'"><div class="notif-title">'+escapeHtml(n.title||'Update')+'</div><div class="notif-msg">'+linkify(n.message||'')+'</div><div class="notif-time">'+ds+'</div>'+ah+'</li>';});le.innerHTML=html;if(be){if(uc>0){be.innerText=uc>99?'99+':uc;be.style.display="block";}else be.style.display="none";}}
function markAllNotificationsAsRead(){var ri=safeGetJSON('read_notif_ids',[]);var seen={};ri.forEach(function(x){seen[x]=1;});globalNotifications.forEach(function(n){seen[n.id]=1;});try{localStorage.setItem('read_notif_ids',JSON.stringify(Object.keys(seen)));}catch(e){}renderNotificationDropdown();}
async function syncRealtimeDatabase(){try{var nn=[];var nr=await fetch(FIREBASE_BASE_URL+'/notifications.json');if(nr.ok){var nd=await nr.json();if(nd)Object.keys(nd).forEach(function(id){nn.push(Object.assign({id:id},nd[id]));});}if(currentUser){var ids=[String(currentUser.rblxUserId||'').toLowerCase(),(currentUser.gmail||'').toLowerCase(),(currentUser.username||'').toLowerCase()];for(var ii=0;ii<ids.length;ii++){var id=ids[ii];if(!id)continue;var ur=await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(id)+'.json');if(ur.ok){var ud=await ur.json();if(ud)Object.keys(ud).forEach(function(k){nn.push(Object.assign({id:k},ud[k]));});}}}if(currentUser&&isOwnerOrCoOwner(currentUser)){var oa=await fetch(FIREBASE_BASE_URL+'/owner_alerts.json');if(oa.ok){var od=await oa.json();if(od)Object.keys(od).forEach(function(id){nn.push(Object.assign({id:id},od[id]));});}}if(currentUser&&isStaff(currentUser)){var rr=await fetch(FIREBASE_BASE_URL+'/reports.json');if(rr.ok){var rd=await rr.json();if(rd){globalReports=[];Object.keys(rd).forEach(function(id){globalReports.push(Object.assign({id:id},rd[id]));});}}}try{var aU=await fetch(FIREBASE_BASE_URL+'/users.json');if(aU.ok){var aD=await aU.json();if(aD){var all=safeGetJSON('app_users_db',[]);Object.keys(aD).forEach(function(k){var u=aD[k];if(u&&u.rblxUserId){var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(u.rblxUserId)){ix=i;break;}}if(ix===-1)all.push(u);else all[ix]=Object.assign({},all[ix],u);}});if(all.length>500){all.sort(function(a,b){return (new Date(b.lastSeen||0).getTime())-(new Date(a.lastSeen||0).getTime());});all=all.slice(0,500);if(currentUser&&!all.some(function(u){return String(u.rblxUserId)===String(currentUser.rblxUserId);}))all.push(currentUser);}try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}if(currentUser){var me=null;for(var j=0;j<all.length;j++){if(String(all[j].rblxUserId)===String(currentUser.rblxUserId)){me=all[j];break;}}if(me){var sc=currentUser.shopCart;Object.keys(me).forEach(function(k){if(me[k]!==undefined&&k!=='shopCart'&&_CLIENT_OWNED_FIELDS.indexOf(k)===-1)currentUser[k]=me[k];});currentUser.shopCart=sc||currentUser.shopCart||[];try{localStorage.setItem('app_current_user',JSON.stringify(currentUser));}catch(e){}}}}}}catch(e){}try{var vs=await fetch(FIREBASE_BASE_URL+'/img_shots.json');if(vs.ok){var vd=await vs.json();if(vd){var rm=Object.keys(vd).map(function(k){return vd[k];}).filter(function(v){return v&&v.mediaType==='image';});var lc=getAllImgShots();var mp={};lc.forEach(function(v){mp[v.id]=v;});rm.forEach(function(v){if(!mp[v.id])mp[v.id]=v;else mp[v.id]=Object.assign({},mp[v.id],v);});saveAllImgShots(Object.keys(mp).map(function(k){return mp[k];}));}}}catch(e){}try{var lc2=await fetch(FIREBASE_BASE_URL+'/limited_cashout.json');if(lc2.ok){var ld=await lc2.json();if(ld&&ld.expiresAt&&ld.expiresAt>Date.now())globalLimitedCashOut=ld;else globalLimitedCashOut=null;}}catch(e){}try{var pr=await fetch(FIREBASE_BASE_URL+'/xdrg_shop/products.json');if(pr.ok){var pd=await pr.json();if(pd){var np=[];Object.keys(pd).forEach(function(id){np.push(Object.assign({id:id},pd[id]));});saveAllShopProducts(np);}}}catch(e){}try{var or=await fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders.json');if(or.ok){var od2=await or.json();if(od2){var no=[];Object.keys(od2).forEach(function(id){no.push(Object.assign({id:id},od2[id]));});saveAllShopOrders(no);}}}catch(e){}try{var gs=await fetch(FIREBASE_BASE_URL+'/xdrg_game_setup.json');if(gs.ok){var gd=await gs.json();if(gd){if(gd.crystal_items)saveCustomCrystalItems(gd.crystal_items);if(gd.brainrots_items)saveCustomBrainrotsItems(gd.brainrots_items);}}}catch(e){}if(currentUser){try{var fr=await fetch(FIREBASE_BASE_URL+'/friend_requests.json');if(fr.ok){var fd=await fr.json();globalFriendRequests=[];if(fd)Object.keys(fd).forEach(function(id){var r=fd[id];if(r&&(String(r.to).toLowerCase()===String(currentUser.rblxUserId).toLowerCase()||(r.toEmail||'').toLowerCase()===(currentUser.gmail||'').toLowerCase()))globalFriendRequests.push(Object.assign({id:id},r));});}}catch(e){}}if(currentUser){try{var ms=await fetch(FIREBASE_BASE_URL+'/messages.json');if(ms.ok){var md=await ms.json();globalMessages=[];if(md){Object.keys(md).forEach(function(id){var m=md[id];if(m&&(String(m.from)===String(currentUser.rblxUserId)||String(m.to)===String(currentUser.rblxUserId)))globalMessages.push(Object.assign({id:id},m));});globalMessages.sort(function(a,b){return (a.timestamp||0)-(b.timestamp||0);});}}}catch(e){}}nn.sort(function(a,b){var ap=(a.isCashOutCode||a.isAccountLockNotif)?1:0;var bp=(b.isCashOutCode||b.isAccountLockNotif)?1:0;if(ap!==bp)return bp-ap;return (b.timestamp||0)-(a.timestamp||0);});globalNotifications.forEach(function(l){if((l.isCashOutCode||l.isAccountLockNotif)&&!nn.find(function(x){return x.id===l.id;}))nn.unshift(l);});globalNotifications=nn;renderNotificationDropdown();try{var p2=await fetch(FIREBASE_BASE_URL+'/polls.json');if(p2.ok){var pd2=await p2.json();var np2=[];if(pd2)Object.keys(pd2).forEach(function(id){np2.push(Object.assign({id:id},pd2[id]));});globalPolls=np2;}}catch(e){}if(currentUser&&isOwnerOrCoOwner(currentUser)){try{var cr=await fetch(FIREBASE_BASE_URL+'/cashouts.json');if(cr.ok){var cd2=await cr.json();var cl=[];if(cd2)Object.keys(cd2).forEach(function(id){cl.push(Object.assign({id:id},cd2[id]));});globalCashOuts=cl;}}catch(e){}}var t=document.getElementById('pageTitle');if(t&&/Cash/.test(t.innerText)&&currentUser&&isOwnerOrCoOwner(currentUser)&&!isUserTypingCashOut)softRefreshOwnerDashboard();if(document.getElementById('msgLayout'))refreshMessengerUI();if(document.getElementById('pvGrid'))renderProfileViewersContent();if(currentUser)enforceBanKick();}catch(e){console.warn(e);}}
function openProfileViewers(){var t=document.getElementById('pageTitle');if(t)t.innerText='👥 Profile Viewers';var c=document.getElementById('pageContent');if(!c)return;c.innerHTML='<div class="pv-tab-bar"><div class="pv-tab '+(pvTab==='all'?'active':'')+'" onclick="pvSetTab(\'all\')">All</div><div class="pv-tab '+(pvTab==='friends'?'active':'')+'" onclick="pvSetTab(\'friends\')">Friends</div></div><input type="text" class="pv-search" placeholder="🔍 Search..." value="'+escapeHtml(pvSearch)+'" oninput="pvSearch=this.value;renderProfileViewersContent();"><div id="pvGrid" class="pv-grid"></div>';renderProfileViewersContent();}
function pvSetTab(t){pvTab=t;openProfileViewers();}
function renderProfileViewersContent(){var g=document.getElementById('pvGrid');if(!g)return;var ru=safeGetJSON('app_users_db',[]);if(currentUser){var mi=-1;for(var i=0;i<ru.length;i++){if(String(ru[i].rblxUserId)===String(currentUser.rblxUserId)){mi=i;break;}}if(mi!==-1)ru[mi]=Object.assign({},ru[mi],currentUser);else ru.push(currentUser);}var bu=getBotUsers();var all=ru.concat(bu);if(pvTab==='friends'){var fids=(currentUser.friends||[]).map(String);all=ru.filter(function(u){return fids.indexOf(String(u.rblxUserId))!==-1;});}if(pvSearch){var q=pvSearch.toLowerCase();all=all.filter(function(u){return (u.name||'').toLowerCase().indexOf(q)!==-1||(u.username||'').toLowerCase().indexOf(q)!==-1;});}all=all.slice(0,300);g.innerHTML='<div style="grid-column:1/-1;text-align:center;color:#54595d;font-size:.9rem;margin-bottom:10px">📊 '+all.length.toLocaleString()+'+ users</div>'+all.map(function(u){var isMe=currentUser&&String(u.rblxUserId)===String(currentUser.rblxUserId);var on=isUserOnline(u)||u.followerCount;var sd=on?'<span class="pv-status-dot pv-online"></span>ONLINE':'<span class="pv-status-dot pv-offline"></span>OFFLINE';var fs=u.followerCount?'none':getFriendStatus(u);var isF=currentUser&&(currentUser.following||[]).map(String).indexOf(String(u.rblxUserId))!==-1;var fc=u.followerCount||((u.followers||[]).length);var fg=u.followingCount||((u.following||[]).length);var vb=verifiedBadgeHtml(u);var ab=getAgeBadge(u);var fb='';if(!isMe&&!u.followerCount){if(fs==='friends')fb='<button class="pv-btn pv-btn-friend friends" onclick="openMessenger(\''+u.rblxUserId+'\')">✅ Friends — Chat</button>';else if(fs==='pending')fb='<button class="pv-btn pv-btn-friend" style="background:#ffc107;color:#000">⏳ Pending</button>';else fb='<button class="pv-btn pv-btn-friend" onclick="sendFriendRequest(\''+u.rblxUserId+'\')">➕ Add Friend</button>';}var gb=isMe?'':'<button class="pv-btn" style="background:#f59e0b" onclick="openGiftModal(\''+u.rblxUserId+'\',\''+escapeHtml((u.username||u.name||'').replace(/'/g,"\\'"))+'\')">🎁 Gift</button>';var fw=isMe||u.followerCount?'':'<button class="pv-btn" style="background:'+(isF?'#28a745':'#ec4899')+'" onclick="followUserToggle(\''+u.rblxUserId+'\');setTimeout(renderProfileViewersContent,150);">'+(isF?'✓ Following':'➕ Follow')+'</button>';var cc=u.banner?'pv-card has-banner':'pv-card';var bh=u.banner?'<img class="profile-banner" src="'+u.banner+'">':'';return '<div class="'+cc+'">'+bh+'<div class="pv-card-header"><img src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold;font-size:1rem">'+escapeHtml(u.name||'Unknown')+' '+(isMe?'(You)':'')+vb+ab+'</div><div style="color:#54595d;font-size:.8rem">@'+escapeHtml(u.username||'user')+'</div><div style="font-size:.75rem;margin-top:3px">'+getRoleLabel(u)+'</div>'+(u.customStatus?'<div class="custom-status-pill">'+escapeHtml(u.customStatus)+'</div>':'')+'</div></div><div class="pv-info"><div><b>FOLLOWERS:</b> '+fc.toLocaleString()+'</div><div><b>FOLLOWING:</b> '+fg.toLocaleString()+'</div><div><b>STATUS:</b> '+sd+'</div><div><b>AGE:</b> '+(u.verifiedAge?'✅ '+escapeHtml(String(u.verifiedAgeValue)):'❌ Not verified')+'</div>'+(u.points?'<div><b>COINS:</b> '+u.points.toLocaleString()+'</div>':'')+'</div><div class="pv-actions">'+fb+gb+fw+'</div></div>';}).join('');}
function getFriendStatus(u){if(!currentUser)return 'none';if((currentUser.friends||[]).map(String).indexOf(String(u.rblxUserId))!==-1)return 'friends';var o=globalFriendRequests.find(function(r){return String(r.from)===String(currentUser.rblxUserId)&&String(r.to)===String(u.rblxUserId);});if(o)return 'pending';return 'none';}
async function sendFriendRequest(tid){if(!currentUser)return;if(String(tid)===String(currentUser.rblxUserId)){showToast("❌ Can't add yourself","error");return;}var rid="FR-"+Date.now();var d={id:rid,from:currentUser.rblxUserId,fromName:currentUser.name,fromUsername:currentUser.username,to:tid,timestamp:Date.now(),status:'pending'};try{await fetch(FIREBASE_BASE_URL+'/friend_requests/'+rid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(d)});var nid="N-"+Date.now();await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(tid).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"👥 New Friend Request",message:currentUser.name+' sent you a friend request!',timestamp:Date.now(),isFriendRequest:true})});showToast("✅ Sent!","success");}catch(e){showToast("❌ Error","error");}}
async function openFriendConfirmation(){var t=document.getElementById('pageTitle');if(t)t.innerText='💌 Friend Confirmation';var inc=globalFriendRequests.filter(function(r){return String(r.to)===String(currentUser.rblxUserId);});var out=globalFriendRequests.filter(function(r){return String(r.from)===String(currentUser.rblxUserId);});var all=safeGetJSON('app_users_db',[]);var h='<p style="color:#54595d;font-size:.9rem">Manage your friends.</p>';if(inc.length>0){h+='<h2>📩 Incoming ('+inc.length+')</h2>';h+=inc.map(function(r){var u=null;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(r.from)){u=all[i];break;}}if(!u)u={name:r.fromName,rblxUserId:r.from};return '<div class="pv-card" style="margin-bottom:10px"><div class="pv-card-header"><img src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold">'+escapeHtml(u.name||'Unknown')+'</div></div></div><div class="pv-actions"><button class="pv-btn pv-btn-friend friends" onclick="acceptFriendRequest(\''+r.id+'\',\''+r.from+'\')">✅ Accept</button><button class="pv-btn" style="background:#dc3545" onclick="declineFriendRequest(\''+r.id+'\')">❌ Decline</button></div></div>';}).join('');}if(inc.length===0&&out.length===0)h+='<div style="padding:30px;text-align:center;color:#777">No friend requests yet.</div>';h+='<h2>👥 My Friends ('+(currentUser.friends||[]).length+')</h2><div class="pv-grid" id="friendsGrid"></div>';var c=document.getElementById('pageContent');if(c)c.innerHTML=h;var fg=document.getElementById('friendsGrid');var fids=(currentUser.friends||[]).map(String);if(fids.length===0)fg.innerHTML='<div style="padding:20px;color:#777">No friends yet.</div>';else fg.innerHTML=all.filter(function(u){return fids.indexOf(String(u.rblxUserId))!==-1;}).map(function(u){return '<div class="pv-card"><div class="pv-card-header"><img src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold">'+escapeHtml(u.name||'Unknown')+'</div></div></div><div class="pv-actions"><button class="pv-btn pv-btn-message" onclick="openMessenger(\''+u.rblxUserId+'\')">💬 Chat</button><button class="pv-btn pv-btn-view" onclick="removeFriend(\''+u.rblxUserId+'\')">Remove</button></div></div>';}).join('');}
async function acceptFriendRequest(rid,fid){if(!currentUser)return;if(!currentUser.friends)currentUser.friends=[];if(currentUser.friends.map(String).indexOf(String(fid))===-1)currentUser.friends.push(String(fid));saveUserData();var all=safeGetJSON('app_users_db',[]);var fi=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(fid)){fi=i;break;}}if(fi!==-1){if(!all[fi].friends)all[fi].friends=[];if(all[fi].friends.map(String).indexOf(String(currentUser.rblxUserId))===-1)all[fi].friends.push(String(currentUser.rblxUserId));try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}await fetch(FIREBASE_BASE_URL+'/users/'+fid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(all[fi])}).catch(function(){});}try{await fetch(FIREBASE_BASE_URL+'/friend_requests/'+rid+'.json',{method:"DELETE"});}catch(e){}showToast("✅ Added!","success");syncRealtimeDatabase();openFriendConfirmation();}
async function declineFriendRequest(rid){if(!confirm("Decline?"))return;try{await fetch(FIREBASE_BASE_URL+'/friend_requests/'+rid+'.json',{method:"DELETE"});}catch(e){}showToast("Declined","info");syncRealtimeDatabase();openFriendConfirmation();}
async function removeFriend(fid){if(!confirm("Remove friend?"))return;currentUser.friends=(currentUser.friends||[]).filter(function(f){return String(f)!==String(fid);});saveUserData();showToast("Removed","info");openFriendConfirmation();}
function openMessenger(tid){if(!currentUser)return;var all=safeGetJSON('app_users_db',[]);var t=null;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(tid)){t=all[i];break;}}if(!t){showToast("❌ User not found","error");return;}activeConvUserId=tid;var pt=document.getElementById('pageTitle');if(pt)pt.innerText='💌 Messenger';var c=document.getElementById('pageContent');if(!c)return;c.innerHTML='<div class="msg-layout" id="msgLayout"><div class="msg-sidebar"><div class="msg-sidebar-header">💬 Conversations</div><div id="msgConvList"></div></div><div class="msg-main"><div class="msg-header"><img src="'+getRobloxAvatarUrl(t.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold">'+escapeHtml(t.name||'User')+verifiedBadgeHtml(t)+'</div><div style="font-size:.75rem;color:#54595d">@'+escapeHtml(t.username||'user')+'</div></div></div><div class="msg-body" id="msgBody"></div><div class="msg-input-bar"><input type="text" id="msgInput" placeholder="Type..." autocomplete="off"><button type="button" class="msg-send-btn" onclick="sendMessage()">Send</button></div></div></div>';refreshMessengerUI();}
function refreshMessengerUI(){if(!currentUser||!activeConvUserId)return;var all=safeGetJSON('app_users_db',[]);var cl=document.getElementById('msgConvList');if(cl){var fids=(currentUser.friends||[]).map(String);if(fids.length===0)cl.innerHTML='<div style="padding:15px;color:#777;font-size:.85rem">No friends.</div>';else cl.innerHTML=all.filter(function(u){return fids.indexOf(String(u.rblxUserId))!==-1;}).map(function(u){var a=String(u.rblxUserId)===String(activeConvUserId);return '<div class="msg-conv '+(a?'active':'')+'" onclick="openMessenger(\''+u.rblxUserId+'\')"><img src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div style="flex:1;overflow:hidden"><div style="font-weight:bold;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escapeHtml(u.name||'User')+'</div><div style="font-size:.7rem;color:#777">@'+escapeHtml(u.username||'user')+'</div></div></div>';}).join('');}var mb=document.getElementById('msgBody');if(mb){var conv=globalMessages.filter(function(m){return (String(m.from)===String(currentUser.rblxUserId)&&String(m.to)===String(activeConvUserId))||(String(m.from)===String(activeConvUserId)&&String(m.to)===String(currentUser.rblxUserId));});if(conv.length===0)mb.innerHTML='<div style="text-align:center;color:#777;padding:20px">No messages yet. Say hi! 👋</div>';else mb.innerHTML=conv.map(function(m){var y=String(m.from)===String(currentUser.rblxUserId);var d=m.timestamp?new Date(m.timestamp).toLocaleString([],{hour:'2-digit',minute:'2-digit'}):'';return '<div class="msg-bubble '+(y?'msg-you':'msg-him')+'">'+linkify(m.text||'')+'<div class="msg-time">'+d+'</div></div>';}).join('');mb.scrollTop=mb.scrollHeight;}}
async function sendMessage(){if(!currentUser||!activeConvUserId)return;var inp=document.getElementById('msgInput');if(!inp)return;var t=(inp.value||'').trim();if(!t)return;var mid="MSG-"+Date.now();var md={id:mid,from:String(currentUser.rblxUserId),fromName:currentUser.name,to:String(activeConvUserId),text:t,timestamp:Date.now()};inp.value='';globalMessages.push(md);refreshMessengerUI();try{await fetch(FIREBASE_BASE_URL+'/messages/'+mid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(md)});var nid="N-"+Date.now();await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(activeConvUserId).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"💬 New Message",message:currentUser.name+': '+t.substring(0,80),timestamp:Date.now(),isNewMessage:true,fromUserId:String(currentUser.rblxUserId)})}).catch(function(){});}catch(e){showToast("❌ Failed","error");}}
