function toggleAutomationCashOut(on){if(!currentUser)return;currentUser.automationCashOut=on;saveUserData();renderSettingsPage();showToast(on?"⚡ ON":"❌ OFF","info");}
function saveAutoCashOut(){if(!currentUser)return;currentUser.autoCashOutName=(document.getElementById('autoNameInput').value||'').trim();currentUser.autoCashOutNumber=(document.getElementById('autoNumberInput').value||'').trim();saveUserData();showToast("✅ Saved","success");}
function changePassword(){if(!currentUser)return;var o=(document.getElementById('chPasswordOld').value||'').trim();var n=(document.getElementById('chPasswordNew').value||'').trim();if(o!==currentUser.password){showToast("❌ Incorrect","error");return;}currentUser.password=n;saveUserData();showToast("✅ Changed","success");renderSettingsPage();}
function changeName(){if(!currentUser)return;if(currentUser.changeNameCount>=1){showToast("❌ Already used","error");return;}var n=(document.getElementById('chNameInput').value||'').trim();if(!n){showToast("❌ Enter name","error");return;}if(!confirm("⚠️ ONE TIME ONLY. Continue?"))return;currentUser.name=n;currentUser.displayName=n;currentUser.changeNameCount=1;saveUserData();updateUserStatusHeader();showToast("✅ Changed","success");renderSettingsPage();}
function changeNumber(){if(!currentUser)return;currentUser.number=(document.getElementById('chNumberInput').value||'').trim();saveUserData();showToast("✅ Changed","success");renderSettingsPage();}
function changeGmail(){if(!currentUser)return;currentUser.gmail=(document.getElementById('chGmailInput').value||'').trim();saveUserData();showToast("✅ Changed","success");renderSettingsPage();}
function handleAvatarUpload(input){if(!currentUser)return;var f=input.files&&input.files[0];if(!f)return;if(f.size>2*1024*1024){showToast('❌ Max 2MB','error');input.value='';return;}if((f.type||'').indexOf('image/')!==0){showToast('❌ Images only','error');input.value='';return;}var r=new FileReader();r.onload=function(e){var im=new Image();im.onload=function(){var cv=document.createElement('canvas');cv.width=200;cv.height=200;var ctx=cv.getContext('2d');ctx.beginPath();ctx.arc(100,100,100,0,Math.PI*2);ctx.closePath();ctx.clip();var ra=Math.max(200/im.width,200/im.height);var w=im.width*ra,h=im.height*ra;ctx.drawImage(im,(200-w)/2,(200-h)/2,w,h);currentUser.customAvatar=cv.toDataURL('image/jpeg',0.85);saveUserData();showToast('✅ Avatar updated!','success');renderSettingsPage();updateUserStatusHeader();};im.src=e.target.result;};r.readAsDataURL(f);}
function removeCustomAvatar(){if(!currentUser)return;currentUser.customAvatar='';saveUserData();renderSettingsPage();updateUserStatusHeader();showToast('Avatar reset','info');}
function handleBannerUpload(input){if(!currentUser)return;var f=input.files&&input.files[0];if(!f)return;if(f.size>3*1024*1024){showToast('❌ Max 3MB','error');input.value='';return;}if((f.type||'').indexOf('image/')!==0){showToast('❌ Images only','error');input.value='';return;}var r=new FileReader();r.onload=function(e){var im=new Image();im.onload=function(){var cv=document.createElement('canvas');cv.width=1500;cv.height=500;var ctx=cv.getContext('2d');var ra=Math.max(1500/im.width,500/im.height);var w=im.width*ra,h=im.height*ra;ctx.drawImage(im,(1500-w)/2,(500-h)/2,w,h);currentUser.banner=cv.toDataURL('image/jpeg',0.82);saveUserData();showToast('✅ Banner updated!','success');renderSettingsPage();};im.src=e.target.result;};r.readAsDataURL(f);}
function removeBanner(){if(!currentUser)return;currentUser.banner='';saveUserData();renderSettingsPage();showToast('✅ Removed','info');}
function saveCustomStatus(){if(!currentUser)return;var i=document.getElementById('customStatusInput');if(!i)return;currentUser.customStatus=(i.value||'').trim().substring(0,80);currentUser.customStatusUpdatedAt=Date.now();saveUserData();showToast('✅ Status updated!','success');renderSettingsPage();}
function getUserAchievements(u){if(!u)return [];var ul=[];ACHIEVEMENTS.forEach(function(a){try{if(a.check(u))ul.push(a.id);}catch(e){}});return ul;}
function renderAchievementGrid(u){var ul=getUserAchievements(u);return '<div class="achv-grid">'+ACHIEVEMENTS.map(function(a){var has=ul.indexOf(a.id)!==-1;return '<div class="achv-card '+(has?'':'locked')+'" title="'+escapeHtml(a.name)+': '+escapeHtml(a.desc)+'" style="border-color:'+(has?'#fbbf24':'#d1d5db')+';background:'+(has?'linear-gradient(135deg,#fef3c7,#fde68a)':'#f3f4f6')+'"><div class="achv-icon">'+a.icon+'</div><div style="font-size:.7rem;font-weight:bold;margin-top:4px;color:'+(has?'#92400e':'#54595d')+'">'+escapeHtml(a.name)+'</div></div>';}).join('')+'</div>';}
function addToInventory(name,rarity,meta){if(!currentUser)return;if(!currentUser.inventory)currentUser.inventory=[];currentUser.inventory.push({id:'INV-'+Date.now()+'-'+Math.floor(Math.random()*9999),name:name,rarity:rarity||'Common',meta:meta||{},acquiredAt:Date.now()});saveUserData();}
function openInventory(){if(!currentUser){showToast('❌ Login required','error');return;}var t=document.getElementById('pageTitle');if(t)t.innerText='🎒 My Inventory';var inv=currentUser.inventory||[];var c=document.getElementById('pageContent');if(!c)return;if(inv.length===0){c.innerHTML='<div class="empty-state"><div class="icon">🎒</div><p>Empty. Claim quest rewards to fill it!</p></div>';return;}var gr={};inv.forEach(function(it){if(!gr[it.rarity])gr[it.rarity]=[];gr[it.rarity].push(it);});var or=['Godly','Limited','Mythic','Legendary','Epic','Rare','Uncommon','Common'];var h='<p style="color:#54595d">Total: <b>'+inv.length+'</b> items</p>';or.forEach(function(r){if(!gr[r]||gr[r].length===0)return;var col=getRarityColor(r);h+='<h2 style="color:'+col+';border-bottom:2px solid '+col+'">'+getRarityEmoji(r)+' '+r+' ('+gr[r].length+')</h2><div class="inv-grid">';gr[r].forEach(function(it){h+='<div class="inv-item" style="border-color:'+col+';box-shadow:0 0 12px '+col+'40"><div style="font-size:2rem">'+getRarityEmoji(r)+'</div><div style="font-weight:bold;font-size:.95rem;margin:6px 0">'+escapeHtml(it.name)+'</div><div class="inv-rarity-pill" style="background:'+col+'">'+r+'</div><div style="font-size:.7rem;color:#777;margin-top:6px">'+new Date(it.acquiredAt).toLocaleDateString()+'</div></div>';});h+='</div>';});c.innerHTML=h;}
function renderCoinBundles(){return '<h2>💰 Coin Bundles</h2><p style="color:#94a3b8;font-size:.9rem">Buy coins with real money. Bonus included!</p><div class="bundle-grid">'+COIN_BUNDLES.map(function(b){return '<div class="bundle-card" style="background:linear-gradient(135deg,'+b.color+'22,'+b.color+'44);border-color:'+b.color+'"><div style="font-size:2.5rem">'+b.emoji+'</div><div style="font-weight:900;font-size:1.1rem;margin:8px 0">'+b.name+'</div><div style="font-size:1.6rem;font-weight:900;color:'+b.color+'">🪙 '+b.coins.toLocaleString()+'</div>'+(b.bonus?'<div style="font-size:.85rem;color:#28a745;font-weight:bold">+'+b.bonus.toLocaleString()+' bonus!</div>':'')+'<div style="margin-top:10px;font-size:1.1rem;font-weight:900">₱'+b.priceMoney.toLocaleString()+'</div><button class="btn-claim" style="width:100%;margin-top:10px;background:'+b.color+'" onclick="buyCoinBundle(\''+b.id+'\')">💳 Buy Now</button></div>';}).join('')+'</div>';}
async function buyCoinBundle(bid){if(!currentUser){showToast('❌ Login','error');return;}var b=null;for(var i=0;i<COIN_BUNDLES.length;i++){if(COIN_BUNDLES[i].id===bid){b=COIN_BUNDLES[i];break;}}if(!b)return;if(!confirm('Buy '+b.name+' for ₱'+b.priceMoney+'?\nYou will get 🪙 '+(b.coins+b.bonus).toLocaleString()+' coins.'))return;var t=b.coins+b.bonus;currentUser.points=(currentUser.points||0)+t;saveUserData();updateUserStatusHeader();try{var nid="BUNDLE-"+Date.now();await fetch(FIREBASE_BASE_URL+'/owner_alerts/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:'💰 Bundle Purchase',message:currentUser.username+' bought '+b.name+' (₱'+b.priceMoney+')',timestamp:Date.now()})});}catch(e){}showToast('🎉 +'+t.toLocaleString()+' Coins!','success');triggerConfetti();sfxCoin();}
function openGiftModal(tid,tn){if(!currentUser){showToast('❌ Login','error');return;}if(String(tid)===String(currentUser.rblxUserId)){showToast("❌ Can't gift yourself","error");return;}var m=document.getElementById('giftModal');if(!m)return;document.getElementById('giftModalTitle').innerText='🎁 Gift Coins to '+tn;document.getElementById('giftModalInfo').innerText='Your balance: 🪙 '+(currentUser.points||0).toLocaleString();document.getElementById('giftAmountInput').value='';document.getElementById('giftMessageInput').value='';m.dataset.targetId=tid;m.dataset.targetName=tn;m.style.display='flex';}
function closeGiftModal(){var m=document.getElementById('giftModal');if(m)m.style.display='none';}
async function submitGift(){if(!currentUser)return;var m=document.getElementById('giftModal');var tid=m.dataset.targetId;var tn=m.dataset.targetName;var amt=parseInt(document.getElementById('giftAmountInput').value,10);var msg=(document.getElementById('giftMessageInput').value||'').trim().substring(0,80);if(isNaN(amt)||amt<1){showToast('❌ Invalid amount','error');return;}if((currentUser.points||0)<amt){showToast('❌ Not enough coins','error');return;}if(!confirm('Send '+amt.toLocaleString()+' coins to '+tn+'?'))return;currentUser.points-=amt;saveUserData();updateUserStatusHeader();var all=safeGetJSON('app_users_db',[]);var ti=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(tid)){ti=i;break;}}if(ti!==-1){all[ti].points=(all[ti].points||0)+amt;try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}}try{if(ti!==-1)await fetch(FIREBASE_BASE_URL+'/users/'+tid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(all[ti])});var nid="GIFT-"+Date.now();await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(tid).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:'🎁 Coin Gift!',message:'@'+(currentUser.username||currentUser.name)+' sent you 🪙 '+amt.toLocaleString()+(msg?' — "'+msg+'"':''),timestamp:Date.now(),isCoinGift:true})});}catch(e){}closeGiftModal();showToast('🎁 Sent '+amt.toLocaleString()+' coins!','success');triggerConfetti();sfxCoin();}
function openGlobalSearch(){var o=document.getElementById('globalSearchOverlay');if(o){o.style.display='flex';o.classList.add('active');document.body.style.overflow='hidden';setTimeout(function(){var i=document.getElementById('globalSearchInputOverlay');if(i)i.focus();},50);}}
function closeGlobalSearch(){var o=document.getElementById('globalSearchOverlay');if(o){o.style.display='none';o.classList.remove('active');}document.body.style.overflow='';}
function gstSetTab(t){gstTab=t;document.querySelectorAll('.gst-tab').forEach(function(b){var on=b.dataset.gst===t;b.classList.toggle('active',on);});runGlobalSearch((document.getElementById('globalSearchInputOverlay')||{}).value||'');}
function runGlobalSearch(q){q=(q||'').trim().toLowerCase();var r=document.getElementById('globalSearchResults');if(!r)return;if(!q){r.innerHTML='<p style="text-align:center;color:#777;padding:30px">🔍 Type to search...</p>';return;}var h='';if(gstTab==='all'||gstTab==='users'){var au=safeGetJSON('app_users_db',[]);var mu=au.filter(function(u){return (u.name||'').toLowerCase().indexOf(q)!==-1||(u.username||'').toLowerCase().indexOf(q)!==-1||String(u.rblxUserId||'').indexOf(q)!==-1;}).slice(0,20);if(mu.length>0){h+='<h4 style="margin:0 0 10px;color:#3366cc">👥 Users ('+mu.length+')</h4>';h+=mu.map(function(u){return '<div class="gso-item" onclick="closeGlobalSearch();openMessenger(\''+u.rblxUserId+'\')"><img class="gso-avatar" src="'+getRobloxAvatarUrl(u.rblxUserId)+'" onerror="this.onerror=null;this.src=\''+DEFAULT_AVATAR+'\'"><div><div style="font-weight:bold;font-size:.9rem">'+escapeHtml(u.name||'Unknown')+verifiedBadgeHtml(u)+'</div><div style="font-size:.75rem;color:#54595d">@'+escapeHtml(u.username||'user')+'</div></div></div>';}).join('');}}if(gstTab==='all'||gstTab==='products'){var pr=getAllShopProducts();var mp=pr.filter(function(p){return (p.name||'').toLowerCase().indexOf(q)!==-1||(p.category||'').toLowerCase().indexOf(q)!==-1;}).slice(0,20);if(mp.length>0){h+='<h4 style="margin:16px 0 10px;color:#8b5cf6">🛍️ Products ('+mp.length+')</h4>';h+=mp.map(function(p){return '<div class="gso-item"><img class="gso-thumb" src="'+escapeHtml(p.image||'')+'" onerror="this.style.background=\'#eaecf0\'"><div><div style="font-weight:bold">'+escapeHtml(p.name)+'</div><div style="font-size:.72rem;color:#8b5cf6">'+escapeHtml(p.category||'')+'</div><div style="font-size:.85rem;color:#28a745;font-weight:bold;margin-top:4px">₱'+(p.priceMoney||0).toLocaleString()+'</div></div></div>';}).join('');}}if(gstTab==='all'||gstTab==='posts'){var sh=getAllImgShots();var ms=sh.filter(function(v){return (v.title||'').toLowerCase().indexOf(q)!==-1||(v.description||'').toLowerCase().indexOf(q)!==-1||(v.code||'').toLowerCase().indexOf(q)!==-1;}).slice(0,20);if(ms.length>0){h+='<h4 style="margin:16px 0 10px;color:#ec4899">🖼️ Posts ('+ms.length+')</h4>';h+=ms.map(function(v){return '<div class="gso-item" onclick="closeGlobalSearch();openVideoShares()"><img class="gso-thumb" src="'+escapeHtml(v.media||'')+'" onerror="this.style.background=\'#eaecf0\'"><div><div style="font-weight:bold">'+escapeHtml(v.title||'Untitled')+'</div><div style="font-size:.72rem;color:#54595d">@'+escapeHtml(v.uploaderUsername||'')+'</div><div style="font-size:.7rem;color:#ec4899;font-family:monospace;margin-top:4px">'+escapeHtml(v.code||'')+'</div></div></div>';}).join('');}}if(gstTab==='all'||gstTab==='achievements'){var ma=ACHIEVEMENTS.filter(function(a){return (a.name||'').toLowerCase().indexOf(q)!==-1||(a.desc||'').toLowerCase().indexOf(q)!==-1;});if(ma.length>0){h+='<h4 style="margin:16px 0 10px;color:#f59e0b">🏆 Achievements ('+ma.length+')</h4>';h+=ma.map(function(a){return '<div class="gso-item"><div style="font-size:2rem">'+a.icon+'</div><div><div style="font-weight:bold">'+escapeHtml(a.name)+'</div><div style="font-size:.75rem;color:#54595d">'+escapeHtml(a.desc)+'</div></div></div>';}).join('');}}if(!h)h='<p style="text-align:center;color:#777;padding:30px">No results for "<b>'+escapeHtml(q)+'</b>"</p>';r.innerHTML=h;}
function openGalleryModal(pid){if(!currentUser)return;var ps=getAllShopProducts();var p=null;for(var i=0;i<ps.length;i++){if(ps[i].id===pid){p=ps[i];break;}}if(!p||!p.images||p.images.length===0)return;var m=document.getElementById('galleryModal');if(!m)return;document.getElementById('galleryTitle').innerText=p.name;var h='<img id="galleryMainImg" class="gallery-main" src="'+escapeHtml(p.images[0])+'"><div class="gallery-thumbs">';p.images.forEach(function(img,i){h+='<img class="gallery-thumb '+(i===0?'active':'')+'" src="'+escapeHtml(img)+'" onclick="switchGalleryImage(\''+escapeHtml(img)+'\',this)">';});h+='</div>';document.getElementById('galleryContent').innerHTML=h;m.style.display='flex';}
function closeGalleryModal(){var m=document.getElementById('galleryModal');if(m)m.style.display='none';}
function switchGalleryImage(src,el){var mi=document.getElementById('galleryMainImg');if(mi)mi.src=src;document.querySelectorAll('.gallery-thumb').forEach(function(x){x.classList.remove('active');});if(el)el.classList.add('active');}
function openTrading(){if(!currentUser){showToast('❌ Login','error');return;}var t=document.getElementById('pageTitle');if(t)t.innerText='🤝 Trading System';renderTradingPage();openSwapUI('tradingOverlay');}
function renderTradingPage(){var inv=currentUser.inventory||[];var h='<div style="max-width:900px;margin:0 auto"><h2 style="color:#0d9488">🤝 Trading System</h2><p style="font-size:.9rem;color:#94a3b8">Trade items with other players.</p>';h+='<div style="background:rgba(13,148,136,.15);border:1px solid #0d9488;border-radius:8px;padding:12px;margin-bottom:15px"><label style="font-weight:bold;color:#5eead4;font-size:.85rem">Trade with:</label><input type="text" id="tradePartnerInput" placeholder="Roblox ID / username" value="'+(_tradePartnerId||'')+'" style="width:100%;padding:8px;border:1px solid #0d9488;border-radius:6px;margin-top:6px;background:rgba(0,0,0,.3);color:#fff">';if(_tradePartnerId){var p=findUserByIdentifier(_tradePartnerId);if(p)h+='<div style="font-size:.82rem;margin-top:8px;color:#5eead4">✅ Trading with: <b>'+escapeHtml(p.name)+'</b></div>';}h+='</div>';h+='<div class="trade-layout"><div class="trade-side"><h4>🎁 Your Offer</h4><div id="tradeMineList">'+_renderTradeItems(_tradeOfferMine,'mine')+'</div><hr><label style="font-size:.82rem;font-weight:bold;color:#54595d">Add from Inventory:</label><select id="tradeAddSelect" style="width:100%;padding:8px;border:1px solid #a2a9b1;border-radius:6px;margin-top:6px">';if(inv.length===0)h+='<option value="">— Empty —</option>';else h+=inv.map(function(it){return '<option value="'+it.id+'">'+getRarityEmoji(it.rarity)+' '+escapeHtml(it.name)+' ('+it.rarity+')</option>';}).join('');h+='</select><button class="btn-save" style="margin-top:8px;width:100%" onclick="addTradeOffer(\'mine\')">➕ Add</button></div>';h+='<div class="trade-side"><h4>📥 Their Offer</h4><div id="tradeTheirsList">'+_renderTradeItems(_tradeOfferTheirs,'theirs')+'</div></div></div>';h+='<div style="text-align:center;margin-top:20px"><button class="btn-claim" style="background:linear-gradient(135deg,#10b981,#059669);padding:16px 40px;font-size:1.1rem;font-weight:900" onclick="submitTradeOffer()">🤝 Propose Trade</button></div>';h+='<div id="tradeStatusBox" style="margin-top:20px"></div></div>';var c=document.getElementById('tradingContent');if(c)c.innerHTML=h;}
function _renderTradeItems(arr,side){if(!arr||arr.length===0)return '<p style="color:#94a3b8;font-size:.82rem;padding:8px;text-align:center">No items yet</p>';return arr.map(function(it,i){return '<div class="trade-item"><span>'+getRarityEmoji(it.rarity)+' '+escapeHtml(it.name)+'</span><button onclick="removeTradeItem(\''+side+'\','+i+')">Remove</button></div>';}).join('');}
function addTradeOffer(side){if(side!=='mine')return;var pid=(document.getElementById('tradePartnerInput')||{}).value;if(pid&&pid.trim())_tradePartnerId=pid.trim();var sel=document.getElementById('tradeAddSelect');if(!sel)return;var iid=sel.value;if(!iid)return;var inv=currentUser.inventory||[];var item=null;for(var i=0;i<inv.length;i++){if(inv[i].id===iid){item=inv[i];break;}}if(!item)return;for(var j=0;j<_tradeOfferMine.length;j++){if(_tradeOfferMine[j].id===iid){showToast('Already added','info');return;}}_tradeOfferMine.push({id:item.id,name:item.name,rarity:item.rarity});renderTradingPage();}
function removeTradeItem(side,i){if(side==='mine')_tradeOfferMine.splice(i,1);else _tradeOfferTheirs.splice(i,1);renderTradingPage();}
async function submitTradeOffer(){var pidInput=(document.getElementById('tradePartnerInput')||{}).value;if(!pidInput||!pidInput.trim()){showToast('❌ Enter partner','error');return;}_tradePartnerId=pidInput.trim();var partner=findUserByIdentifier(_tradePartnerId);if(!partner){showToast('❌ Not found','error');return;}if(String(partner.rblxUserId)===String(currentUser.rblxUserId)){showToast('❌ Cannot trade with yourself','error');return;}if(_tradeOfferMine.length===0){showToast('❌ Offer empty','error');return;}var tid="TRADE-"+Date.now();var td={id:tid,from:currentUser.rblxUserId,fromName:currentUser.name,to:partner.rblxUserId,toName:partner.name,offer:_tradeOfferMine,status:'pending',timestamp:Date.now()};try{await fetch(FIREBASE_BASE_URL+'/trades/'+tid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(td)});var nid="N-"+Date.now();await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(partner.rblxUserId).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"🤝 Trade Offer",message:currentUser.name+' wants to trade '+_tradeOfferMine.length+' item(s)',timestamp:Date.now()})});document.getElementById('tradeStatusBox').innerHTML='<div class="trade-banner">✅ Trade Proposed!<div style="font-size:.9rem;margin-top:6px;font-weight:normal">Waiting for '+escapeHtml(partner.name)+'...</div></div>';showToast('🤝 Trade sent!','success');}catch(e){showToast('❌ Failed','error');}}
async function checkIncomingTrades(){if(!currentUser)return;try{var r=await fetch(FIREBASE_BASE_URL+'/trades.json');if(!r.ok)return;var d=await r.json();if(!d)return;var mine=Object.values(d).filter(function(t){return t&&String(t.to)===String(currentUser.rblxUserId)&&t.status==='pending';});if(mine.length>0){_tradeOfferTheirs=mine[0].offer||[];if(document.getElementById('tradeMineList'))renderTradingPage();}}catch(e){}}
function openStaffCommands(){if(!currentUser||!isStaff(currentUser)){showToast("❌ Staff only!","error");return;}var t=document.getElementById('pageTitle');if(t)t.innerText='🛡️ Staff Commands';renderStaffCommandsPage();}
function toggleAccordion(id){var a=document.getElementById(id),p=document.getElementById(id+'_panel');if(!a||!p)return;a.classList.toggle('active');p.classList.toggle('active');}
function findUserByIdentifier(id){var t=String(id||'').trim().toLowerCase();if(!t)return null;var all=safeGetJSON('app_users_db',[]);if(currentUser&&!all.find(function(u){return String(u.rblxUserId)===String(currentUser.rblxUserId);}))all.push(currentUser);for(var i=0;i<all.length;i++){var u=all[i];if(String(u.rblxUserId||'').toLowerCase()===t||(u.gmail||'').toLowerCase()===t||(u.username||'').toLowerCase()===t||(u.name||'').toLowerCase()===t)return u;}return null;}
function warnBlock(p){return '<label>Message:</label><textarea id="'+p+'WarnMessage" rows="3"></textarea><label>User:</label><input type="text" id="'+p+'WarnTarget"><button class="btn-save" style="width:100%;background:#ff9800;color:#000" onclick="warnUser(\''+p+'\')">⚠️ Send Warning</button>';}
function kickBlock(p,m){return '<label>User:</label><input type="text" id="'+p+'KickTarget"><label>Duration ('+m+' max):</label><div style="display:flex;gap:8px;margin-bottom:10px"><input type="number" id="'+p+'KickAmount" min="1" value="1" style="flex:1;padding:8px;border:1px solid #a2a9b1;border-radius:4px"><select id="'+p+'KickUnit" style="flex:1;padding:8px;border:1px solid #a2a9b1;border-radius:4px"><option value="seconds">Seconds</option><option value="minutes">Minutes</option><option value="hours">Hours</option><option value="days">Days</option></select></div><label>Reason:</label><input type="text" id="'+p+'KickReason"><button class="btn-save" style="width:100%;background:#ffc107;color:#000" onclick="kickUser(\''+p+'\')">⏸️ Kick</button>';}
function banBlock(p){return '<label>User:</label><input type="text" id="'+p+'BanTarget"><label>Reason:</label><input type="text" id="'+p+'BanReason"><button class="btn-danger" style="width:100%" onclick="banUser(\''+p+'\')">🚫 Ban</button>';}
function modRoleBlock(p){return '<label>Target:</label><input type="text" id="'+p+'ModTarget"><div style="display:flex;gap:10px"><button class="btn-save" style="flex:1;background:#28a745" onclick="updateUserRole(\''+p+'ModTarget\',\'Moderator\',\'give\')">Give Mod</button><button class="btn-danger" style="flex:1" onclick="updateUserRole(\''+p+'ModTarget\',\'Moderator\',\'remove\')">Remove</button></div>';}
function adminRoleBlock(p){return '<label>Target:</label><input type="text" id="'+p+'AdminTarget"><div style="display:flex;gap:10px"><button class="btn-save" style="flex:1;background:#007bff" onclick="updateUserRole(\''+p+'AdminTarget\',\'Admin\',\'give\')">Give Admin</button><button class="btn-danger" style="flex:1" onclick="updateUserRole(\''+p+'AdminTarget\',\'Admin\',\'remove\')">Remove</button></div>';}
function coinGiverBlock(p){return '<label>Target:</label><input type="text" id="'+p+'GrantTarget"><label>Amount:</label><input type="number" id="'+p+'GrantAmount"><button class="btn-save" style="width:100%;background:#28a745" onclick="grantCoinsToUser(\''+p+'\')">⚡ Give Coins</button>';}
function pollBlock(p){return '<label>Title:</label><input type="text" id="'+p+'PollTitle"><label>Description:</label><input type="text" id="'+p+'PollDesc"><label>Options (comma):</label><input type="text" id="'+p+'PollOptions"><label>Image:</label><input type="file" id="'+p+'PollImage" accept="image/*"><button class="btn-save" style="width:100%;background:#28a745" onclick="createPollWithImage(\''+p+'\')">⚡ Create Poll</button>';}
