function verifiedBadgeBlock(p){return '<label>Target:</label><input type="text" id="'+p+'VerifiedTarget"><div style="display:flex;gap:10px"><button class="btn-save" style="flex:1;background:#1DA1F2;color:#fff" onclick="giveVerifiedBadge(\''+p+'\')">🔵 Give</button><button class="btn-danger" style="flex:1" onclick="removeVerifiedBadge(\''+p+'\')">Remove</button></div>';}
function limitedCashOutBlock(p){return '<div style="background:linear-gradient(135deg,#fff3cd,#ffe0b2);border:2px dashed #f59e0b;border-radius:8px;padding:14px;margin-bottom:12px"><h4 style="margin:0 0 10px;color:#b45309">🤑 Limited Cash Out</h4><label>Money (₱):</label><input type="number" id="'+p+'LcoMoney" value="20" min="1"><label>Duration:</label><input type="number" id="'+p+'LcoDuration" value="1" min="1"><select id="'+p+'LcoUnit"><option value="minutes">Minutes</option><option value="hours" selected>Hours</option><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option><option value="years">Years</option></select><label>Cost Coins:</label><input type="number" id="'+p+'LcoCostCoins" value="20000" min="1"><button class="btn-save" style="width:100%;background:linear-gradient(135deg,#ff6b6b,#feca57);color:#fff;font-weight:900;padding:14px" onclick="activateLimitedCashOut(\''+p+'\')">🚀 Activate</button><button class="btn-danger" style="width:100%;margin-top:8px" onclick="deactivateLimitedCashOut()">❌ Cancel</button></div>';}
function xdrgShopOwnerBlock(p){return '<div style="background:#f3e8ff;border:2px solid #8b5cf6;border-radius:8px;padding:14px;margin-bottom:12px"><h4 style="margin:0 0 10px;color:#6366f1">🛍️ Create Product</h4><label>Name:</label><input type="text" id="'+p+'ProdName"><label>Price (₱):</label><input type="number" id="'+p+'ProdPriceMoney" value="0" min="0"><label>Price (🪙):</label><input type="number" id="'+p+'ProdPriceCoins" value="0" min="0"><label>Category:</label><select id="'+p+'ProdCategory"><option value="T-shirt">T-shirt</option><option value="Pants">Pants</option><option value="Staff Toy">Staff Toy</option><option value="Customize">Customize</option><option value="Accessories">Accessories</option><option value="Other">Other</option></select><label>Description:</label><textarea id="'+p+'ProdDesc" rows="2"></textarea><label>Main Image:</label><input type="file" id="'+p+'ProdImage" accept="image/*"><label>Extra Images (up to 4):</label><input type="file" id="'+p+'ProdImages" accept="image/*" multiple><button class="btn-save" style="width:100%;background:#8b5cf6;color:#fff;font-weight:900;padding:12px" onclick="createXdrgProduct(\''+p+'\')">🛍️ Create Product</button><hr style="margin:16px 0;border:0;border-top:1px solid #c4b5fd"><h4>📦 Manage Orders</h4><div id="'+p+'ShopOrdersList">Loading...</div><button class="btn-save" style="width:100%;background:#6366f1;color:#fff;margin-top:8px" onclick="loadShopOrdersInStaff(\''+p+'\')">🔄 Refresh Orders</button></div>';}
function gameSetupBlock(p){return '<div style="background:linear-gradient(135deg,#0ea5e9,#0369a1);border-radius:8px;padding:16px;margin-bottom:12px;color:#fff"><h4 style="margin:0 0 10px">🎮 Game Setup</h4><button class="btn-save" style="width:100%;background:#fff;color:#0369a1;font-weight:900;padding:12px;margin-bottom:8px" onclick="openGameSetup(\'crystal\')">💎 Crystal Setup</button><button class="btn-save" style="width:100%;background:#fff;color:#0369a1;font-weight:900;padding:12px" onclick="openGameSetup(\'brainrots\')">🚂 Brainrots Setup</button></div>';}
function renderStaffCommandsPage(){if(!currentUser||!isStaff(currentUser))return;var iO=isOwnerAccount(currentUser);var iCO=isCoOwner(currentUser);var iA=isUserAdmin(currentUser);var iM=isUserModerator(currentUser);var iOL=iO||iCO;var html='<p style="font-size:.85rem;color:#54595d">Click a section to expand.</p>';if(iM||iA||iOL){html+='<button class="accordion" id="accMod" onclick="toggleAccordion(\'accMod\')">🔰 Moderator Commands</button><div class="panel" id="accMod_panel"><h4>⚠️ Warn</h4>'+warnBlock('mod')+'<h4 style="margin-top:20px">⏸️ Kick</h4>'+kickBlock('mod','7 days')+'<h4 style="margin-top:20px;color:#c82333">🚫 Ban</h4>'+banBlock('mod')+'</div>';}if(iA||iOL){html+='<button class="accordion" id="accAdmin" onclick="toggleAccordion(\'accAdmin\')">🛡️ Admin Commands</button><div class="panel" id="accAdmin_panel"><h4>⚠️ Warn</h4>'+warnBlock('adm')+'<h4 style="margin-top:20px">⏸️ Kick</h4>'+kickBlock('adm','30 days')+'<h4 style="margin-top:20px;color:#c82333">🚫 Ban</h4>'+banBlock('adm')+'<hr><h4>🔰 Mod Role</h4>'+modRoleBlock('adm')+'<hr><h4>🪙 Coin Giver</h4>'+coinGiverBlock('adm')+'<hr><h4>📊 Poll</h4>'+pollBlock('adm')+'<hr><h4>📢 Announcement</h4>'+announcementBlock('adm')+'</div>';}if(iOL){html+='<button class="accordion" id="accOwner" onclick="toggleAccordion(\'accOwner\')">👑 '+(iO?'Owner':'Co-Owner')+' Commands</button><div class="panel" id="accOwner_panel">';if(iO){html+='<h4 style="color:#7a00ff">👑 Owner Management</h4><label>Target:</label><input type="text" id="ownAddTarget"><div style="display:flex;gap:10px"><button class="btn-save" style="flex:1;background:linear-gradient(45deg,#ff0055,#7a00ff);color:#fff" onclick="addOwnerOrCoOwner(\'Owner\')">👑 Owner</button><button class="btn-save" style="flex:1;background:linear-gradient(45deg,#ff8c00,#ffd700);color:#000" onclick="addOwnerOrCoOwner(\'Co-Owner\')">🥇 Co-Owner</button></div><div style="display:flex;gap:10px;margin-top:8px"><button class="btn-danger" style="flex:1" onclick="removeOwnerOrCoOwner(\'Owner\')">Remove Owner</button><button class="btn-danger" style="flex:1" onclick="removeOwnerOrCoOwner(\'Co-Owner\')">Remove Co-Owner</button></div><hr>';}html+='<h4>🎮 Game Setup</h4>'+gameSetupBlock('own')+'<hr><h4>🔵 Verified</h4>'+verifiedBadgeBlock('own')+'<hr><h4>🛍️ XDRG Shop</h4>'+xdrgShopOwnerBlock('own')+'<hr><h4>🤑 Limited Cash Out</h4>'+limitedCashOutBlock('own')+'<hr><h4>🪪 Age Requests</h4><div id="ageRequestsList" style="margin-bottom:10px">Loading...</div><button class="btn-save" style="width:100%;background:#8b5cf6;color:#fff" onclick="loadAgeRequestsInStaff()">🔄 Refresh</button><hr><h4>⚠️ Warn</h4>'+warnBlock('own')+'<h4 style="margin-top:20px">⏸️ Kick</h4>'+kickBlock('own','100 days')+'<h4 style="margin-top:20px;color:#c82333">🚫 Ban</h4>'+banBlock('own')+'<button class="btn-save" style="width:100%;background:#6c757d;margin-top:8px" onclick="unbanUser(\'own\')">✅ Unban User</button><hr><h4>🛡️ Admin Role</h4>'+adminRoleBlock('own')+'<hr><h4>🔰 Mod Role</h4>'+modRoleBlock('own')+'<hr><h4>🪙 Coin Giver</h4>'+coinGiverBlock('own')+'<hr><h4>📊 Poll</h4>'+pollBlock('own')+'<hr><h4>📢 Announcement</h4>'+announcementBlock('own')+'<hr><h4 style="color:#dc3545">🔴 Notification</h4><label>Audience:</label><select id="ownNotifAudience" onchange="document.getElementById(\'ownNotifTargetBox\').style.display=this.value===\'specific\'?\'block\':\'none\'"><option value="everyone">Everyone</option><option value="specific">Specific</option></select><div id="ownNotifTargetBox" style="display:none;margin-top:8px"><label>Target:</label><input type="text" id="ownNotifTarget"></div><label>Title:</label><input type="text" id="ownNotifTitle"><label>Message:</label><textarea id="ownNotifMsg" rows="3"></textarea><button class="btn-save" style="width:100%;background:#dc3545;margin-top:10px" onclick="sendGlobalOwnerNotification()">Send</button><hr><h4 style="color:#9b59b6">🛡️ Sneak Peek</h4><label>Title:</label><input type="text" id="ownSneakTitle"><label>Description:</label><textarea id="ownSneakDesc" rows="3"></textarea><label>Image:</label><input type="file" id="ownSneakImage" accept="image/*"><button class="btn-save" style="width:100%;background:#9b59b6;margin-top:10px" onclick="uploadSneakPeek()">Upload</button></div>';}var c=document.getElementById('pageContent');if(c)c.innerHTML=html;if(iOL)setTimeout(function(){loadAgeRequestsInStaff();if(document.getElementById('ownShopOrdersList')){_staffShopPrefix='own';loadShopOrdersInStaff('own');}},100);}
async function loadAgeRequestsInStaff(){var el=document.getElementById('ageRequestsList');if(!el)return;try{var r=await fetch(FIREBASE_BASE_URL+'/age_requests.json');var d=await r.json();if(!d||Object.keys(d).length===0){el.innerHTML='<p style="color:#777;font-size:.85rem">No age requests.</p>';return;}var l=Object.values(d).filter(function(x){return x&&x.status==='pending';}).sort(function(a,b){return (b.timestamp||0)-(a.timestamp||0);});if(l.length===0){el.innerHTML='<p style="color:#777;font-size:.85rem">No pending requests.</p>';return;}el.innerHTML=l.map(function(r){return '<div style="background:#f8f5ff;border:1px solid #c4b5fd;border-radius:6px;padding:10px;margin-bottom:8px"><div style="font-weight:bold;color:#6366f1">'+(r.type==='appeal'?'📩 Appeal':'🪪 New')+': '+escapeHtml(r.userName)+'</div><div style="font-size:.8rem;color:#54595d;margin:4px 0">Est: <b>'+escapeHtml(String(r.estimatedAge))+'</b></div><button class="btn-action-sm" style="background:#8b5cf6" onclick="openAgeRequest(\''+r.id+'\')">📃 Review</button></div>';}).join('');}catch(e){el.innerHTML='<p style="color:#dc3545">Failed.</p>';}}
async function loadShopOrdersInStaff(p){_staffShopPrefix=p;var el=document.getElementById(p+'ShopOrdersList');if(!el)return;try{var r=await fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders.json');var d=await r.json();if(!d||Object.keys(d).length===0){el.innerHTML='<p style="color:#777;font-size:.85rem">No orders.</p>';return;}var l=Object.values(d).filter(function(x){return x&&x.status==='Pending';}).sort(function(a,b){return (b.timestamp||0)-(a.timestamp||0);});if(l.length===0){el.innerHTML='<p style="color:#777;font-size:.85rem">No pending orders.</p>';return;}el.innerHTML=l.map(function(o){return '<div style="background:#fff;border:1px solid #c4b5fd;border-radius:6px;padding:10px;margin-bottom:8px;font-size:.85rem"><div style="font-weight:bold;color:#6366f1">'+escapeHtml(o.id)+' — '+escapeHtml(o.userName)+'</div><div>Total: ₱'+(o.totalMoney||0).toLocaleString()+'</div><div>Payment: '+escapeHtml(o.payment||'N/A')+' · Status: '+escapeHtml(o.paymentStatus||'N/A')+'</div><div>Logistics: '+escapeHtml(o.logistics||'N/A')+'</div><div>Ship: '+escapeHtml(o.shipping.name)+', '+escapeHtml(o.shipping.number)+'</div><div>Addr: '+escapeHtml(o.shipping.address)+', '+escapeHtml(o.shipping.postal)+'</div><div style="display:flex;gap:6px;margin-top:6px;flex-wrap:wrap"><input type="text" id="ord_'+escapeHtml(o.id)+'_txt" placeholder="Order ID" value="'+escapeHtml(o.orderIdText||'')+'" style="flex:1;min-width:100px;padding:6px;border:1px solid #a2a9b1;border-radius:4px"><input type="text" id="ord_'+escapeHtml(o.id)+'_addr" placeholder="Address Process" value="'+escapeHtml(o.addressProcess||'')+'" style="flex:1;min-width:100px;padding:6px;border:1px solid #a2a9b1;border-radius:4px"><button class="btn-action-sm" onclick="saveShopOrderInfo(\''+o.id+'\')">Save</button></div></div>';}).join('');}catch(e){el.innerHTML='<p style="color:#dc3545">Failed.</p>';}}
async function saveShopOrderInfo(oid){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;var tid=((document.getElementById('ord_'+oid+'_txt')||{}).value||'').trim();var addr=((document.getElementById('ord_'+oid+'_addr')||{}).value||'').trim();var o=getAllShopOrders();var ix=-1;for(var i=0;i<o.length;i++){if(o[i].id===oid){ix=i;break;}}if(ix===-1){showToast('❌ Not in cache','error');return;}o[ix].orderIdText=tid;o[ix].addressProcess=addr;o[ix].status='Processing';saveAllShopOrders(o);try{await fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders/'+oid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(o[ix])});showToast("✅ Saved!","success");loadShopOrdersInStaff(_staffShopPrefix||'own');}catch(e){showToast("❌ Error","error");}}
async function warnUser(p){if(!currentUser||!isStaff(currentUser))return;var m=document.getElementById(p+'WarnMessage').value.trim();var t=document.getElementById(p+'WarnTarget').value.trim();if(!m||!t){showToast("❌ Fill all","error");return;}var u=findUserByIdentifier(t);if(!u){showToast("❌ Not found","error");return;}var sr=getSenderRoleLabel(currentUser);var nid="WARN-"+Date.now();var nd={id:nid,title:'⚠️ Warning from '+sr,message:m,timestamp:Date.now(),isWarning:true,warnedBy:currentUser.username||currentUser.name,warnedByRole:sr};try{await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(u.rblxUserId).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(nd)});showToast("⚠️ Sent!","success");}catch(e){showToast("❌ Failed","error");}}
async function kickUser(p){if(!currentUser||!isStaff(currentUser))return;var t=document.getElementById(p+'KickTarget').value.trim();var a=parseFloat(document.getElementById(p+'KickAmount').value);var u=document.getElementById(p+'KickUnit').value;var r=document.getElementById(p+'KickReason').value.trim()||'Violation';if(!t||isNaN(a)||a<=0){showToast("❌ Valid inputs","error");return;}var usr=findUserByIdentifier(t);if(!usr){showToast("❌ Not found","error");return;}if(isOwnerAccount(usr)&&!isOwnerAccount(currentUser)){showToast("👑 Can't kick Owner","error");return;}var mlt=u==='seconds'?1000:u==='minutes'?60000:u==='hours'?3600000:86400000;var ms=a*mlt;var iA=isUserAdmin(currentUser);var iOL=isOwnerOrCoOwner(currentUser);var max=iOL?100*86400000:(iA?30*86400000:7*86400000);if(ms>max){showToast("❌ Max exceeded","error");return;}var ku=Date.now()+ms;var all=safeGetJSON('app_users_db',[]);var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(usr.rblxUserId)){ix=i;break;}}var upd=Object.assign({},usr,{kickUntil:ku,kickReason:r,kickedBy:currentUser.username||currentUser.name});if(ix!==-1)all[ix]=upd;else all.push(upd);try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/users/'+usr.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(upd)});showToast('⏸️ Kicked for '+a+' '+u,'success');}catch(e){showToast("❌ Failed","error");}}
async function banUser(p){if(!currentUser||!isStaff(currentUser))return;var t=document.getElementById(p+'BanTarget').value.trim();var r=document.getElementById(p+'BanReason').value.trim()||'Violation';if(!t){showToast("❌ Enter user","error");return;}var usr=findUserByIdentifier(t);if(!usr){showToast("❌ Not found","error");return;}if(isOwnerAccount(usr)&&!isOwnerAccount(currentUser)){showToast("👑 Can't ban Owner","error");return;}if(!confirm('Ban '+(usr.name||usr.username)+'?'))return;var all=safeGetJSON('app_users_db',[]);var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(usr.rblxUserId)){ix=i;break;}}var upd=Object.assign({},usr,{isBanned:true,banReason:r,bannedBy:currentUser.username||currentUser.name,kickUntil:0});if(ix!==-1)all[ix]=upd;else all.push(upd);try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/users/'+usr.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(upd)});showToast('🚫 Banned.','success');}catch(e){showToast("❌ Failed","error");}}
async function unbanUser(p){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;var t=document.getElementById(p+'BanTarget').value.trim();var usr=findUserByIdentifier(t);if(!usr){showToast("❌ Not found","error");return;}var all=safeGetJSON('app_users_db',[]);var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(usr.rblxUserId)){ix=i;break;}}var upd=Object.assign({},usr,{isBanned:false,banReason:'',kickUntil:0});if(ix!==-1)all[ix]=upd;try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/users/'+usr.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(upd)});showToast('✅ Unbanned','success');}catch(e){showToast("❌ Failed","error");}}
async function giveVerifiedBadge(p){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;var t=document.getElementById(p+'VerifiedTarget').value.trim();var usr=findUserByIdentifier(t);if(!usr){showToast("❌ Not found","error");return;}if(usr.isVerified){showToast("ℹ️ Already","info");return;}var all=safeGetJSON('app_users_db',[]);var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(usr.rblxUserId)){ix=i;break;}}var upd=Object.assign({},usr,{isVerified:true,verifiedExpiry:0});if(ix!==-1)all[ix]=upd;else all.push(upd);try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/users/'+usr.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(upd)});var nid="VB-"+Date.now();await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(usr.rblxUserId).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"You Receive An Verified Badge",message:"congratulations you been receive an Verified Badge",timestamp:Date.now(),isVerifiedBadge:true})});showToast('🔵 Given','success');}catch(e){showToast("❌ Failed","error");}}
async function removeVerifiedBadge(p){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;var t=document.getElementById(p+'VerifiedTarget').value.trim();var usr=findUserByIdentifier(t);if(!usr){showToast("❌ Not found","error");return;}var all=safeGetJSON('app_users_db',[]);var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(usr.rblxUserId)){ix=i;break;}}var upd=Object.assign({},usr,{isVerified:false,verifiedExpiry:0});if(ix!==-1)all[ix]=upd;try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/users/'+usr.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(upd)});showToast('✅ Removed','success');}catch(e){showToast("❌ Failed","error");}}
async function addOwnerOrCoOwner(t){if(!currentUser||!isOwnerAccount(currentUser))return;var tg=document.getElementById('ownAddTarget').value.trim();var usr=findUserByIdentifier(tg);if(!usr){showToast("❌ Not found","error");return;}if(!confirm('Promote '+(usr.name||usr.username)+' to '+t+'?'))return;var all=safeGetJSON('app_users_db',[]);var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(usr.rblxUserId)){ix=i;break;}}var upd=Object.assign({},usr);if(t==='Owner'){upd.isOwner=true;upd.isAdmin=true;upd.role='Owner';}else{upd.isCoOwner=true;upd.isAdmin=true;upd.role='Co-Owner';}if(ix!==-1)all[ix]=upd;else all.push(upd);try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/users/'+usr.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(upd)});showToast('👑 Done','success');renderStaffCommandsPage();}catch(e){showToast("❌ Failed","error");}}
async function removeOwnerOrCoOwner(t){if(!currentUser||!isOwnerAccount(currentUser))return;var tg=document.getElementById('ownAddTarget').value.trim();var usr=findUserByIdentifier(tg);if(!usr){showToast("❌ Not found","error");return;}if(String(usr.rblxUserId)===String(currentUser.rblxUserId)){showToast("❌ Can't remove yourself","error");return;}if(!confirm('Remove '+t+'?'))return;var all=safeGetJSON('app_users_db',[]);var ix=-1;for(var i=0;i<all.length;i++){if(String(all[i].rblxUserId)===String(usr.rblxUserId)){ix=i;break;}}var upd=Object.assign({},usr);if(t==='Owner'){upd.isOwner=false;upd.role=upd.isCoOwner?'Co-Owner':(upd.isAdmin?'Admin':'Member');}else{upd.isCoOwner=false;upd.role=upd.isAdmin?'Admin':'Member';}if(ix!==-1)all[ix]=upd;try{localStorage.setItem('app_users_db',JSON.stringify(all));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/users/'+usr.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(upd)});showToast('✅ Removed','success');renderStaffCommandsPage();}catch(e){showToast("❌ Failed","error");}}
async function createAnnouncement(p){if(!currentUser||!isUserAdmin(currentUser))return;var t=document.getElementById(p+'AnnTitle').value.trim();var m=document.getElementById(p+'AnnMessage').value.trim();if(!t||!m){showToast("❌ Fill all","error");return;}var nid="ANN-"+Date.now();var nd={id:nid,title:'📢 '+t,message:m,timestamp:Date.now(),isAnnouncement:true,sender:currentUser.name||currentUser.username,senderRole:getSenderRoleLabel(currentUser)};try{await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(nd)});showToast("📢 Deployed!","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function updateUserRole(ti,role,action){if(!currentUser)return;if(role==='Admin'&&!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only","error");return;}if(role==='Moderator'&&!isOwnerOrCoOwner(currentUser)&&!isUserAdmin(currentUser)){showToast("❌ Staff only","error");return;}var el=document.getElementById(ti);var tt=el?el.value.trim().toLowerCase():'';if(!tt){showToast("❌ Enter target","error");return;}var au=safeGetJSON('app_users_db',[]);var fi=-1;for(var i=0;i<au.length;i++){if(String(au[i].rblxUserId||'').toLowerCase()===tt||(au[i].gmail||'').toLowerCase()===tt||(au[i].username||'').toLowerCase()===tt){fi=i;break;}}if(fi===-1){showToast("❌ Not found","error");return;}var tu=au[fi];if(isOwnerAccount(tu)){showToast('👑 Owner','error');return;}if(action==='give'){if(role==='Admin'){tu.isAdmin=true;tu.role='Admin';}else{tu.isMod=true;tu.role=tu.isAdmin?'Admin':'Moderator';}}else{if(role==='Admin'){tu.isAdmin=false;tu.role=tu.isMod?'Moderator':'Member';}else{tu.isMod=false;tu.role=tu.isAdmin?'Admin':'Member';}}au[fi]=tu;try{localStorage.setItem('app_users_db',JSON.stringify(au));}catch(e){}try{await fetch(FIREBASE_BASE_URL+'/users/'+tu.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(tu)});showToast('✅ Done','success');}catch(e){showToast("❌ Error","error");}renderStaffCommandsPage();}
async function createPollWithImage(p){var t=document.getElementById(p+'PollTitle').value.trim();var d=document.getElementById(p+'PollDesc').value.trim();var os=document.getElementById(p+'PollOptions').value.trim();var fi=document.getElementById(p+'PollImage');if(!t||!os){showToast("❌ Fill all","error");return;}var opt=os.split(',').map(function(o){return {name:o.trim(),votes:0};}).filter(function(o){return o.name!=="";});if(opt.length<2){showToast("❌ 2+ options","error");return;}var sp=async function(img){var pid='poll_'+Date.now();var po={id:pid,title:t,description:d,options:opt,timestamp:Date.now()};if(img)po.image=img;try{await fetch(FIREBASE_BASE_URL+'/polls/'+pid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(po)});showToast("✅ Created!","success");syncRealtimeDatabase();openStaffCommands();}catch(e){showToast("❌ Error","error");}};if(fi.files.length>0){var f=fi.files[0];if(f.size>2*1024*1024){showToast("❌ Max 2MB","error");return;}var r=new FileReader();r.onload=function(e){sp(e.target.result);};r.readAsDataURL(f);}else sp(null);}
async function sendGlobalOwnerNotification(){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;var t=document.getElementById('ownNotifTitle').value.trim();var m=document.getElementById('ownNotifMsg').value.trim();var a=document.getElementById('ownNotifAudience').value;var ti=document.getElementById('ownNotifTarget').value.trim().toLowerCase();if(!t||!m){showToast("❌ Fill all","error");return;}var nid="NOTIF-"+Date.now();var nd={id:nid,title:t,message:m,sender:currentUser.name||currentUser.username,senderRole:getSenderRoleLabel(currentUser),timestamp:Date.now()};var ep=FIREBASE_BASE_URL+'/notifications/'+nid+'.json';if(a==='specific')ep=FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(ti)+'/'+nid+'.json';try{await fetch(ep,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(nd)});showToast("📢 Sent!","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function uploadSneakPeek(){if(!currentUser||!isStaff(currentUser))return;var t=document.getElementById('ownSneakTitle').value.trim();var d=document.getElementById('ownSneakDesc').value.trim();var fi=document.getElementById('ownSneakImage');if(!t||!d||fi.files.length===0){showToast("❌ Fill all","error");return;}var f=fi.files[0];if(f.size>2*1024*1024){showToast("❌ Max 2MB","error");return;}var r=new FileReader();r.onload=async function(e){var sid="SNEAK-"+Date.now();try{await fetch(FIREBASE_BASE_URL+'/sneak_peeks/'+sid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:sid,title:t,description:d,image:e.target.result,timestamp:Date.now(),uploader:currentUser.username||currentUser.name})});showToast("✅ Uploaded!","success");syncRealtimeDatabase();}catch(err){showToast("❌ Error","error");}};r.readAsDataURL(f);}
async function grantCoinsToUser(p){if(!currentUser||!isUserAdmin(currentUser)){showToast("❌ Admin+ only","error");return;}var ti=(document.getElementById(p+'GrantTarget').value||'').trim().toLowerCase();var ca=document.getElementById(p+'GrantAmount').value;if(!ti){showToast("❌ Enter target","error");return;}var cta=parseInt(ca,10);if(isNaN(cta)||cta<=0){showToast("❌ Valid amount","error");return;}var au=safeGetJSON('app_users_db',[]);var fi=-1;for(var i=0;i<au.length;i++){if(String(au[i].rblxUserId||'').toLowerCase()===ti||(au[i].gmail||'').toLowerCase()===ti||(au[i].username||'').toLowerCase()===ti){fi=i;break;}}if(fi===-1){showToast("❌ Not found","error");return;}var tu=au[fi];tu.points=(tu.points||0)+cta;tu.lastSeen=new Date().toISOString();au[fi]=tu;try{localStorage.setItem('app_users_db',JSON.stringify(au));}catch(e){}if(String(tu.rblxUserId)===String(currentUser.rblxUserId)){currentUser.points=tu.points;try{localStorage.setItem('app_current_user',JSON.stringify(currentUser));}catch(e){}updateUserStatusHeader();}try{await fetch(FIREBASE_BASE_URL+'/users/'+tu.rblxUserId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(tu)});var nid="CG-"+Date.now();await fetch(FIREBASE_BASE_URL+'/user_notifications/'+encodeURIComponent(String(tu.rblxUserId).toLowerCase())+'/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"🪙 Coins Received!",message:'You received '+cta.toLocaleString()+' Coins!',timestamp:Date.now(),isCoinGift:true})});showToast('⚡ Granted '+cta.toLocaleString(),'success');syncRealtimeDatabase();}catch(e){showToast("❌ Error","error");}}
async function createXdrgProduct(p){if(!currentUser||!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only","error");return;}var nm=document.getElementById(p+'ProdName').value.trim();var pm=parseFloat(document.getElementById(p+'ProdPriceMoney').value)||0;var pc=parseInt(document.getElementById(p+'ProdPriceCoins').value,10)||0;var cat=document.getElementById(p+'ProdCategory').value;var desc=document.getElementById(p+'ProdDesc').value.trim();var fi=document.getElementById(p+'ProdImage');var fmi=document.getElementById(p+'ProdImages');if(!nm){showToast("❌ Enter name","error");return;}if(fi.files.length===0){showToast("❌ Add main image","error");return;}var mf=fi.files[0];if(mf.size>3*1024*1024){showToast("❌ Max 3MB","error");return;}var r=new FileReader();r.onload=async function(e){var pid="PROD-"+Date.now();var extra=[];var extras=[];if(fmi&&fmi.files){for(var k=0;k<fmi.files.length&&k<4;k++){var ef=fmi.files[k];if(ef.size>3*1024*1024)continue;extras.push(ef);}}var readExtra=function(idx){return new Promise(function(res){if(idx>=extras.length){res();return;}var rr=new FileReader();rr.onload=function(ee){extra.push(ee.target.result);readExtra(idx+1).then(res);};rr.readAsDataURL(extras[idx]);});};await readExtra(0);var prod={id:pid,name:nm,priceMoney:pm,priceCoins:pc,category:cat,description:desc,image:e.target.result,images:[e.target.result].concat(extra),createdBy:currentUser.username||currentUser.name,timestamp:Date.now()};var all=getAllShopProducts();all.push(prod);saveAllShopProducts(all);try{await fetch(FIREBASE_BASE_URL+'/xdrg_shop/products/'+pid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(prod)});showToast("✅ Created!","success");renderStaffCommandsPage();}catch(err){showToast("❌ Error","error");}};r.readAsDataURL(mf);}
async function activateLimitedCashOut(p){if(!currentUser||!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only","error");return;}var m=parseInt(document.getElementById(p+'LcoMoney').value,10);var d=parseInt(document.getElementById(p+'LcoDuration').value,10);var u=document.getElementById(p+'LcoUnit').value;var cc=parseInt(document.getElementById(p+'LcoCostCoins').value,10);if(isNaN(m)||m<1||isNaN(d)||d<1||isNaN(cc)||cc<1){showToast("❌ Valid inputs","error");return;}var mlt={minutes:60000,hours:3600000,days:86400000,weeks:604800000,months:2592000000,years:31536000000};var ea=Date.now()+d*mlt[u];var obj={money:m,costCoins:cc,expiresAt:ea,activatedBy:currentUser.username||currentUser.name,activatedAt:Date.now()};try{await fetch(FIREBASE_BASE_URL+'/limited_cashout.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(obj)});var nid="LCO-"+Date.now();await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"Limited Cash Out 🤑🎉!!!",message:'cash out now the limited Cash out until Limited Cash out is banish!🎉📌 ₱'+m,timestamp:Date.now(),isLimitedCashOut:true,money:m})});globalLimitedCashOut=obj;showToast("🚀 ACTIVATED!","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
async function deactivateLimitedCashOut(){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;if(!confirm("Cancel?"))return;try{await fetch(FIREBASE_BASE_URL+'/limited_cashout.json',{method:"DELETE"});globalLimitedCashOut=null;showToast("✅ Cancelled","success");syncRealtimeDatabase();}catch(e){showToast("❌ Failed","error");}}
function openGameSetup(t){if(!currentUser||!isOwnerOrCoOwner(currentUser)){showToast("❌ Owner only!","error");return;}currentSetupType=t;editingSetupIndex=-1;if(t==='crystal'){currentSetupItems=getCustomCrystalItems().slice();document.getElementById('gameSetupTitle').innerText='💎 Crystal Setup';}else{currentSetupItems=getCustomBrainrotsItems().slice();document.getElementById('gameSetupTitle').innerText='🚂 Brainrots Setup';}renderGameSetup();var o=document.getElementById('gameSetupOverlay');if(o)o.classList.add('active');document.body.style.overflow='hidden';}
function closeGameSetup(){var o=document.getElementById('gameSetupOverlay');if(o)o.classList.remove('active');document.body.style.overflow='';}
function renderGameSetup(){var c=document.getElementById('gameSetupContent');if(!c)return;var isC=currentSetupType==='crystal';var ttl=isC?'💎 Crystal':'🚂 Brainrots';var h='<div class="age-form-box"><h3>'+ttl+' — Item Setup</h3><p style="font-size:.88rem;color:#c4b5fd">Fill details, click Next to add.</p>';if(isC){h+='<div class="setup-field"><div><label>Item Name</label><input type="text" id="gsName"></div><div><label>Cost (₱)</label><input type="number" id="gsCost" min="0"></div></div><div class="setup-field"><div><label>Health</label><input type="number" id="gsHealth" min="0"></div><div><label>Duration</label><input type="text" id="gsDuration"></div></div><div class="setup-field"><div><label>Rarity</label><select id="gsRarity"><option>Common</option><option>Rare</option><option>Legendary</option><option>Mythic</option><option>Godly</option><option>Limited</option></select></div><div></div></div>';}else{h+='<div class="setup-field"><div><label>Item Name</label><input type="text" id="gsName"></div><div><label>Cost (₱)</label><input type="number" id="gsCost" min="0"></div></div><div class="setup-field"><div><label>Per Second</label><input type="text" id="gsPerSecond"></div><div><label>Rarity</label><select id="gsRarity"><option>Common</option><option>Rare</option><option>Legendary</option><option>Mythic</option><option>Godly</option><option>Limited</option></select></div></div><div class="setup-field"><div><label>Area</label><input type="text" id="gsArea"></div><div></div></div>';}h+='<div class="setup-actions"><button style="background:#005a9c;color:#fff" onclick="nextGameSetupItem()">➡️ Next</button><button style="background:#28a745;color:#fff" onclick="publishGameSetup()">📤 Publish</button></div></div>';h+='<div style="margin-top:22px"><h3 style="color:#a78bfa">📋 Items ('+currentSetupItems.length+')</h3>';if(currentSetupItems.length===0)h+='<p style="color:#94a3b8;font-size:.85rem">No items yet.</p>';else currentSetupItems.forEach(function(it,i){var ex=isC?('Cost: '+it.cost+' HP: '+it.health+' Dur: '+it.duration+' R: '+it.rarity):('Cost: '+it.cost+' /s: '+it.perSecond+' R: '+it.rarity+' A: '+it.area);h+='<div class="setup-item-row"><div><b>#'+(i+1)+' '+escapeHtml(it.name)+'</b><br><small style="opacity:.75">'+escapeHtml(ex)+'</small></div><div class="sir-actions"><button style="background:#dc3545;color:#fff" onclick="removeGameSetupItem('+i+')">🗑️</button></div></div>';});h+='</div>';if(currentSetupItems.length>0)h+='<div class="setup-actions"><button style="background:#28a745;color:#fff;font-weight:900" onclick="publishGameSetup()">📤 PUBLISH ALL ('+currentSetupItems.length+')</button></div>';h+='<div class="setup-actions"><button style="background:#6c757d;color:#fff" onclick="closeGameSetup()">✕ Close</button></div>';c.innerHTML=h;}
function nextGameSetupItem(){var isC=currentSetupType==='crystal';var nm=(document.getElementById('gsName').value||'').trim();var co=parseFloat(document.getElementById('gsCost').value)||0;var ra=document.getElementById('gsRarity').value;if(!nm){showToast("❌ Enter name","error");return;}var it;if(isC){it={name:nm,cost:co,health:parseFloat(document.getElementById('gsHealth').value)||0,duration:(document.getElementById('gsDuration').value||'').trim(),rarity:ra};}else{it={name:nm,cost:co,perSecond:(document.getElementById('gsPerSecond').value||'').trim(),rarity:ra,area:(document.getElementById('gsArea').value||'').trim()};}if(editingSetupIndex>=0){currentSetupItems[editingSetupIndex]=it;editingSetupIndex=-1;}else currentSetupItems.push(it);['gsName','gsCost','gsHealth','gsDuration','gsPerSecond','gsArea'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});showToast("✅ Item added","success");renderGameSetup();}
function removeGameSetupItem(i){if(i<0||i>=currentSetupItems.length)return;if(!confirm("Remove?"))return;currentSetupItems.splice(i,1);if(editingSetupIndex===i)editingSetupIndex=-1;renderGameSetup();}
async function publishGameSetup(){if(!currentUser||!isOwnerOrCoOwner(currentUser))return;if(currentSetupItems.length===0){showToast("❌ No items","error");return;}var isC=currentSetupType==='crystal';if(isC)saveCustomCrystalItems(currentSetupItems);else saveCustomBrainrotsItems(currentSetupItems);var k=isC?'crystal_items':'brainrots_items';try{await fetch(FIREBASE_BASE_URL+'/xdrg_game_setup/'+k+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(currentSetupItems)});var nid="GS-"+Date.now();await fetch(FIREBASE_BASE_URL+'/notifications/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:"🎮 Game Setup Updated!",message:(isC?'Crystal':'Brainrots')+' updated with '+currentSetupItems.length+' items.',timestamp:Date.now()})});}catch(e){}showToast("✅ Published!","success");syncRealtimeDatabase();closeGameSetup();}
window.onload=function(){try{if("Notification" in window&&Notification.permission!=="granted"&&Notification.permission!=="denied")Notification.requestPermission();var up=new URLSearchParams(window.location.search);var vsCode=up.get('xdrgimg')||up.get('xdrgvideo');var ref=up.get('ref');if(ref){try{localStorage.setItem('activeReferrer',ref);}catch(e){}var ab=document.getElementById('refDetectAlert');if(ab){ab.innerText='🔗 Referral Link Detected!';ab.style.display='block';}}var sl=localStorage.getItem('app_language')||'en';currentLanguage=sl;getBotUsers();var su=safeGetJSON('app_current_user',null);if(su){currentUser=su;var defaults={isHistoryPublic:false,wrongPasswordAttempts:0,accountLockedUntil:0,friends:[],following:[],followers:[],isVerified:false,verifiedExpiry:0,cashBalance:0,extraSpins:0,verifiedAge:false,verifiedAgeValue:null,ageAppealCount:0,lastAgeAppealTime:0,pendingAgeAppeal:null,automationCashOut:false,autoCashOutName:'',autoCashOutNumber:'',changeNameCount:0,changeUserIdCount:0,shopCart:[],inventory:[],darkMode:false,soundEnabled:true,customAvatar:'',banner:'',customStatus:''};Object.keys(defaults).forEach(function(k){if(currentUser[k]===undefined)currentUser[k]=defaults[k];});if(isOwnerAccount(currentUser)){currentUser.isOwner=true;currentUser.isAdmin=true;}updateUserStatusHeader();logDeviceConnection(currentUser);showWiki();applyBackground(currentUser.background||'white');if(currentUser.darkMode)document.body.classList.add('dark');var sb=document.getElementById('soundToggleBtn');if(sb)sb.innerText=currentUser.soundEnabled===false?'🔇':'🔊';var db=document.getElementById('dmToggleBtn');if(db)db.innerText=currentUser.darkMode?'☀️':'🌙';checkDailyReward();enforceBanKick();}setLanguage(sl);document.addEventListener('click',function(){var d=document.getElementById('notifDropdown');if(d)d.classList.remove('active');});var gsi=document.getElementById('globalSearchInput');if(gsi)gsi.addEventListener('input',function(){clearTimeout(gstDebounce);var v=this.value;gstDebounce=setTimeout(function(){runGlobalSearch(v);var ov=document.getElementById('globalSearchInputOverlay');if(ov)ov.value=v;if(v.trim()&&(!document.getElementById('globalSearchOverlay')||document.getElementById('globalSearchOverlay').style.display!=='flex')){var o=document.getElementById('globalSearchOverlay');if(o){o.style.display='flex';o.classList.add('active');document.body.style.overflow='hidden';}}},200);});var gsio=document.getElementById('globalSearchInputOverlay');if(gsio)gsio.addEventListener('input',function(){clearTimeout(gstDebounce);var v=this.value;gstDebounce=setTimeout(function(){runGlobalSearch(v);if(gsi)gsi.value=v;},200);});var gso=document.getElementById('globalSearchOverlay');if(gso)gso.addEventListener('click',function(e){if(e.target===this)closeGlobalSearch();});document.addEventListener('keydown',function(e){if((e.ctrlKey||e.metaKey)&&(e.key==='k'||e.key==='K')){e.preventDefault();openGlobalSearch();}if(e.key==='Escape'){var m=document.getElementById('uploadModal');if(m&&m.classList.contains('active'))closeUploadUI();var gs=document.getElementById('globalSearchOverlay');if(gs&&gs.style.display==='flex')closeGlobalSearch();var gm=document.getElementById('giftModal');if(gm&&gm.style.display==='flex')closeGiftModal();var gal=document.getElementById('galleryModal');if(gal&&gal.style.display==='flex')closeGalleryModal();}});if(syncInterval)clearInterval(syncInterval);syncInterval=setInterval(syncRealtimeDatabase,2000);syncRealtimeDatabase();setTimeout(checkIncomingTrades,2500);setInterval(checkIncomingTrades,15000);if(vsCode)setTimeout(function(){openVideoShares();},600);var gsp=document.getElementById('tradePartnerInput');if(gsp)gsp.addEventListener('input',function(){_tradePartnerId=this.value.trim();});}catch(err){console.error(err);}};
